window.TADABBUR_DHARIYAT = {"_meta":{"description":"تدبّر سورة الذاريات (٥١)، وسورةٌ مكّيّةٌ. محورُها تقريرُ البعثِ والجزاءِ بالقسمِ بالرياحِ والسحابِ والسماء، ووصفُ المتّقين بقيامِ الليلِ والاستغفارِ والإنفاق، والاستدلالُ بالآياتِ في الأرضِ والأنفسِ والسماء، وقصصُ ضيفِ إبراهيمَ وقومِ لوطٍ وموسى وعادٍ وثمودَ ونوح، وأنّ الغايةَ من الخلقِ عبادةُ الله، والأمرُ بالفرارِ إلى الله. فيها «وفي أنفسكم أفلا تبصرون»، و«كانوا قليلا من الليل ما يهجعون»، و«ففروا إلى الله»، و«وما خلقت الجن والإنس إلا ليعبدون».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":51,"name":"الذاريات","total_ayahs":60,"audio":[1,15,17,20,21,23,50,56,58,60],"passages":[{"title":"القسمُ بالآياتِ على صدقِ البعثِ والجزاء","range":[1,6],"theme":"القسمُ بالرياحِ الذارياتِ والسحابِ الحاملاتِ والجارياتِ والملائكةِ المقسّماتِ على أنّ ما توعدون من البعثِ لصادقٌ وأنّ الدينَ والجزاءَ لواقع","verses":[{"n":1,"reflection":{"text":"«والذاريات ذروا»: أقسم الله بالرياحِ التي تذرو الترابَ والحبَّ ذروًا؛ ففي هذا القسمُ بآيةٍ من آياتِ الله؛ فتأمّل الرياحَ آيةً من آياتِ الله المسخّرة، فمن سخّرها قادرٌ على البعثِ الذي أقسم عليه، فتفكّر في آياتِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آياتِ الله المسخّرة، والاستدلالُ بها."},"action":{"text":"تأمّل قسمَ الله بالرياح: أقسم الله بالرياحِ الذارياتِ التي تذرو وتفرّق الترابَ والحبَّ والغبارَ ذروًا في الهواء «والذاريات ذروا»؛ ففي هذا قسمٌ من الله بآيةٍ عظيمةٍ من آياته المسخّرة؛ فأقسم بالرياحِ لعظمِ منفعتها ودلالتها على قدرته؛ فتأمّل أنت الرياحَ آيةً من آياتِ الله المسخّرة لمنافعِ العباد؛ ومن آياته أن يرسل الرياحَ مبشّرات؛ وتصريفِ الرياحِ آياتٌ لقومٍ يعقلون؛ فمن سخّر الرياحَ قادرٌ على ما أقسم عليه من البعثِ والجزاء؛ فتفكّر في آياتِ الله المسخّرة لتستدلّ بها على قدرته ووحدانيته؛ فمن تفكّر في آياتِ الله ازداد إيمانًا؛ فاجعل التفكّرَ في آياتِ الله المسخّرةِ دأبك."}},{"n":2,"reflection":{"text":"«فالحاملات وقرا»، والسحابِ الحاملاتِ للماءِ الثقيل؛ ففي هذا قسمٌ بآيةٍ أخرى؛ فتأمّل السحابَ الحاملَ للماءِ نعمةً من الله، فمن حمّل السحابَ الماءَ قادرٌ على البعث، فاشكر نعمةَ المطرِ واعتبر بآياتِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ المطر، والتفكّرُ في آياتِ الله."},"action":{"text":"تأمّل القسمَ بالسحاب: والسحابِ الحاملاتِ وقرًا، أي حِملًا ثقيلًا من الماء؛ فتحمله وتسوقه بأمرِ الله «فالحاملات وقرا»؛ ففي هذا قسمٌ بالسحابِ الحاملِ للماءِ الثقيل، وهي آيةٌ ونعمةٌ من الله؛ فتأمّل أنت السحابَ الذي يحمل الماءَ الثقيلَ في السماءِ ثم ينزله رحمةً ورزقًا؛ وهو الذي يرسل الرياحَ بشرًا بين يدي رحمته حتى إذا أقلّت سحابًا ثقالًا سقناه لبلدٍ ميّت؛ أفرأيتم الماءَ الذي تشربون؛ فمن حمّل السحابَ الماءَ قادرٌ على البعثِ وإحياءِ الموتى؛ فاشكر نعمةَ المطرِ والسحاب، واعتبر بآياتِ الله في خلقه؛ فمن شكر واعتبر انتفع، ومن غفل حُرِم؛ فاجعل شكرَ النعمِ والتفكّرَ في آياتِ الله دأبك."}},{"n":3,"reflection":{"text":"«فالجاريات يسرا»، والسفنِ الجارياتِ في البحرِ بيسرٍ وسهولة، أو الرياحِ والنجوم؛ ففي هذا قسمٌ بآيةٍ أخرى؛ فتأمّل تسخيرَ الله للجارياتِ ليسرِ حياتك، فمن سخّرها قادرٌ على البعث، فاشكر نعمَ الله واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله المسخّرة، والاعتبارُ بها."},"action":{"text":"تأمّل القسمَ بالجاريات: والجارياتِ يسرًا، وهي السفنُ التي تجري في البحرِ بيسرٍ وسهولةٍ بأمرِ الله، أو الكواكبُ الجاريةُ في أفلاكها، أو الرياحُ الجارية «فالجاريات يسرا»؛ ففي هذا قسمٌ بالجارياتِ التي تجري بيسر، وهي آيةٌ ونعمةٌ من الله؛ فتأمّل أنت تسخيرَ الله للسفنِ والكواكبِ والرياحِ تجري بيسرٍ لمنافعِ العباد؛ الله الذي سخّر لكم البحرَ لتجريَ الفلكُ فيه بأمره؛ وسخّر لكم الشمسَ والقمرَ دائبين؛ فمن سخّرها بيسرٍ قادرٌ على البعثِ الذي أقسم عليه؛ فاشكر نعمَ الله المسخّرةَ لك، واعتبر بها على قدرته ووحدانيته؛ فمن شكر واعتبر اهتدى؛ فاجعل شكرَ نعمِ الله المسخّرةِ والاعتبارَ بها دأبك."}},{"n":4,"reflection":{"text":"«فالمقسمات أمرا»، والملائكةِ المقسّماتِ للأمورِ بأمرِ الله (الأرزاقِ والأقدار)؛ ففي هذا قسمٌ بالملائكةِ المدبّرةِ بأمرِ الله؛ فاعلم أنّ الله يدبّر الأمورَ بملائكته بحكمته، فسلّم لتدبيرِ الله، فالأمرُ كلُّه بيده يقسمه بحكمته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لتدبيرِ الله، وإدراكُ أنّ الأمرَ كلَّه بيده."},"action":{"text":"تأمّل القسمَ بالملائكةِ المقسّمات: والملائكةِ المقسّماتِ أمرًا، أي التي تقسّم الأمورَ بين الخلقِ بأمرِ الله: من الأرزاقِ والآجالِ والأقطارِ والأمطار «فالمقسمات أمرا»؛ ففي هذا قسمٌ بالملائكةِ التي تدبّر وتقسّم الأمورَ بأمرِ الله وإذنه؛ فالملائكةُ منفّذةٌ لأمرِ الله في تدبيرِ الكون؛ فالمدبّراتِ أمرًا؛ فاعلم أنت أنّ الله يدبّر الأمورَ كلَّها بملائكته بحكمته وعلمه؛ فما من رزقٍ ولا قدرٍ إلا وهو مقسّمٌ بأمرِ الله؛ فسلّم لتدبيرِ الله وقسمته؛ نحن قسمنا بينهم معيشتهم في الحياةِ الدنيا؛ فالأمرُ كلُّه بيدِ الله يقسمه بحكمته وعدله؛ فمن سلّم لتدبيرِ الله ورضي بقسمته اطمأنّ، ومن اعترض تعب؛ فاجعل التسليمَ لتدبيرِ الله والرضا بقسمته دأبك."}},{"n":5,"reflection":{"text":"«إنما توعدون لصادق»: إنّ الذي توعدون به من البعثِ والجزاءِ لصدقٌ لا شكَّ فيه؛ ففي هذا تقريرُ صدقِ الوعد؛ فأيقن بصدقِ وعدِ الله بالبعثِ والجزاء، فما وعد الله به صادقٌ واقع، فاستعدّ له بالعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدقِ وعدِ الله بالبعثِ والجزاء، والاستعدادُ له."},"action":{"text":"تأمّل تقريرَ صدقِ الوعد: هذا جوابُ القسم: إنّ الذي توعدون به، أيها الناس، من البعثِ والحسابِ والجزاءِ لصادقٌ حقٌّ لا شكَّ فيه ولا كذب «إنما توعدون لصادق»؛ ففي هذا تقريرُ صدقِ وعدِ الله بالبعثِ والجزاء، مؤكّدًا بالقسمِ بالآياتِ العظيمة؛ فما وعد الله به من البعثِ حقٌّ صادق؛ فأيقن أنت بصدقِ وعدِ الله بالبعثِ والجزاءِ يقينًا جازمًا؛ وعدَ الله حقًّا ومن أصدقُ من الله قيلًا؛ إنّ الساعةَ آتيةٌ لا ريبَ فيها؛ فما وعد الله به صادقٌ واقعٌ لا محالة؛ فاستعدّ للبعثِ والجزاءِ بالإيمانِ والعملِ الصالح؛ فمن أيقن بصدقِ الوعدِ عمل له، ومن شكّ فيه غفل؛ فاجعل يقينك بصدقِ وعدِ الله والاستعدادَ له دأبك."}},{"n":6,"reflection":{"text":"«وإن الدين لواقع»، وإنّ الجزاءَ والحسابَ لواقعٌ لا محالة؛ ففي هذا تأكيدُ وقوعِ الجزاء؛ فأيقن بوقوعِ الجزاءِ والحساب، فالدينُ واقعٌ حتمًا، فاعمل لهذا اليومِ الذي تُجزى فيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوقوعِ الجزاءِ والحساب، والعملُ ليومِ الدين."},"action":{"text":"تأمّل تأكيدَ وقوعِ الجزاء: وإنّ الدينَ، وهو الجزاءُ والحسابُ على الأعمال، لواقعٌ لا محالة، كائنٌ حتمًا؛ فبعد تأكيدِ صدقِ الوعد، أكّد وقوعَ الجزاء «وإن الدين لواقع»؛ ففي هذا تأكيدُ وقوعِ الجزاءِ والحسابِ يومَ القيامة؛ فالجزاءُ واقعٌ حتمًا على كلِّ عمل؛ فأيقن أنت بوقوعِ الجزاءِ والحسابِ يقينًا جازمًا؛ مالكِ يومِ الدين؛ وإنّ الدينَ لواقع؛ يومئذٍ يوفّيهم الله دينهم الحق؛ فكلُّ نفسٍ تُجزى بما كسبت يومَ الدين؛ فاعمل لهذا اليومِ الذي تُجزى فيه بعملك؛ فمن أيقن بوقوعِ الجزاءِ عمل له، ومن أنكره غفل وخسر؛ فاجعل يقينك بوقوعِ الجزاءِ والعملَ ليومِ الدينِ دأبك."}}]},{"title":"اضطرابُ المكذّبين ووعيدُ الخراصين، وجزاءُ الفريقين","range":[7,16],"theme":"القسمُ بالسماءِ ذاتِ الحبك، وأنّ المكذّبين في قولٍ مختلفٍ يُصرَف عن الحقِّ من صُرِف، ولعنُ الخراصين الغافلين الذين يسألون عن يومِ الدينِ استهزاءً فيُفتَنون على النار، ومقابلُ ذلك المتّقون في جنّاتٍ وعيونٍ آخذين ما آتاهم ربّهم لأنهم كانوا محسنين","verses":[{"n":7,"reflection":{"text":"«والسماء ذات الحبك»: أقسم بالسماءِ ذاتِ الطرائقِ الحسنةِ والخَلقِ المحكم؛ ففي هذا قسمٌ بإتقانِ خلقِ السماء؛ فتأمّل إتقانَ خلقِ السماءِ وحسنها، فمن أتقن خلقها قادرٌ على البعث، فاعتبر بإتقانِ خلقِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في إتقانِ خلقِ السماء، والاستدلالِ به."},"action":{"text":"تأمّل القسمَ بإتقانِ السماء: والسماءِ ذاتِ الحبك، أي ذاتِ الطرائقِ الحسنةِ والخَلقِ المتقنِ المحكمِ البديع، كحبكِ الرملِ والماءِ إذا ضربته الريح «والسماء ذات الحبك»؛ ففي هذا قسمٌ بالسماءِ لإتقانِ خلقها وحسنِ نظامها؛ فأقسم بها لعظمتها ودلالتها على قدرته؛ فتأمّل أنت إتقانَ خلقِ السماءِ وحسنها ونظامها البديع؛ الذي خلق سبعَ سماواتٍ طباقًا ما ترى في خلقِ الرحمنِ من تفاوت؛ وزيّنّا السماءَ الدنيا بمصابيح؛ فمن أتقن خلقَ السماءِ المحكمِ قادرٌ على البعثِ الذي أقسم عليه؛ فاعتبر بإتقانِ خلقِ الله على قدرته ووحدانيته؛ فمن تفكّر في خلقِ السماءِ أيقن بالخالقِ وبالبعث؛ فاجعل التفكّرَ في إتقانِ خلقِ السماءِ والاستدلالَ به دأبك."}},{"n":8,"reflection":{"text":"«إنكم لفي قول مختلف»: إنكم، أيها المكذّبون، في قولٍ مختلفٍ مضطربٍ في شأنِ القرآنِ والرسولِ والبعث؛ ففي هذا بيانُ اضطرابِ أقوالِ المكذّبين؛ فاحذر الاضطرابَ في الحقّ، فالباطلُ متناقضٌ مختلف، والحقُّ واحدٌ ثابت، فالزم الحقَّ الواحد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الحقِّ الواحدِ الثابت، والحذرُ من اضطرابِ الباطل."},"action":{"text":"تأمّل اضطرابَ أقوالِ المكذّبين: إنكم، أيها المكذّبون، لفي قولٍ مختلفٍ متناقضٍ مضطرب؛ فمرّةً تقولون في القرآنِ سحر، ومرّةً شعر، ومرّةً كهانة؛ وفي الرسولِ ساحرٌ ومجنونٌ وكاذب؛ وفي البعثِ إنكارٌ وشكّ «إنكم لفي قول مختلف»؛ ففي هذا بيانُ أنّ المكذّبين في قولٍ مضطربٍ متناقضٍ مختلف؛ فتناقضت أقوالهم واضطربت لأنهم على باطل؛ فالباطلُ متناقضٌ مختلف، والحقُّ واحدٌ ثابتٌ منسجم؛ ولو كان من عند غيرِ الله لوجدوا فيه اختلافًا كثيرًا؛ فاحذر أنت الاضطرابَ والتناقضَ في شأنِ الحق؛ والزم الحقَّ الواحدَ الثابتَ المنسجم؛ فأهلُ الحقِّ على قولٍ واحدٍ ثابت، وأهلُ الباطلِ في أقوالٍ مختلفةٍ متناقضة؛ فمن لزم الحقَّ ثبت، ومن اتّبع الباطلَ اضطرب؛ فاجعل لزومَ الحقِّ الواحدِ الثابتِ دأبك."}},{"n":9,"reflection":{"text":"«يؤفك عنه من أفك»: يُصرَف عن الحقِّ والإيمانِ من صُرِف عنه في علمِ الله لإعراضه؛ ففي هذا بيانُ أنّ الصرفَ عن الحقِّ بسببِ الإعراض؛ فاحذر أسبابَ الصرفِ عن الحقِّ من الإعراضِ والعناد، فاطلب الهدايةَ وأقبل على الحق، فمن أعرض عن الحقِّ صُرِف عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الحقِّ وطلبُ الهداية، والحذرُ من أسبابِ الصرف."},"action":{"text":"تأمّل بيانَ الصرفِ عن الحق: يُؤفَك ويُصرَف عن الحقِّ والإيمانِ بالقرآنِ والرسولِ والبعث، من أُفِك وصُرِف عنه في سابقِ علمِ الله، بسببِ إعراضه وعناده وسوءِ اختياره «يؤفك عنه من أفك»؛ ففي هذا بيانُ أنّ من يُصرَف عن الحقِّ إنما يُصرَف بسببِ إعراضه وعناده؛ فالصرفُ عن الحقِّ عقوبةٌ على الإعراض؛ فمن أعرض عن الحقِّ صرفه الله عنه؛ فاحذر أنت أسبابَ الصرفِ عن الحق: من الإعراضِ والعنادِ والكبرِ واتّباعِ الهوى؛ فلمّا زاغوا أزاغ الله قلوبهم؛ فأقبل على الحقِّ واطلب الهدايةَ من الله؛ ويهدي إليه من ينيب؛ والذين اهتدوا زادهم هدًى؛ فمن أقبل على الحقِّ هُدِي إليه، ومن أعرض عنه صُرِف عنه؛ فاجعل الإقبالَ على الحقِّ وطلبَ الهدايةِ والحذرَ من أسبابِ الصرفِ دأبك."}},{"n":10,"reflection":{"text":"«قتل الخراصون»: لُعِن الكذّابون الظانّون الذين يقولون في الدينِ بالظنِّ والتخمين؛ ففي هذا ذمُّ الخرصِ والقولِ بالظنّ؛ فاحذر القولَ في الدينِ بالظنِّ والتخمينِ بلا علم، فقل الحقَّ بعلمٍ ودليل، فالخرصُ والكذبُ في الدينِ ملعون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"القولُ في الدينِ بعلمٍ ودليل، وتركُ الخرصِ والظن."},"action":{"text":"تأمّل ذمَّ الخراصين: قُتِل ولُعِن الخرّاصون، وهم الكذّابون الظانّون الذين يقولون في أمرِ الدينِ والبعثِ بالظنِّ والتخمينِ والحدسِ بلا علمٍ ولا يقين؛ فهم كاذبون خارصون «قتل الخراصون»؛ ففي هذا ذمُّ ولعنُ من يقول في الدينِ بالظنِّ والخرصِ والتخمينِ بلا علم؛ فالخرصُ والقولُ بالظنِّ في الدينِ من صفاتِ المكذّبين؛ فاحذر أنت القولَ في الدينِ بالظنِّ والتخمينِ والحدسِ بلا علمٍ ولا دليل؛ إن يتّبعون إلا الظنَّ وإنّ الظنَّ لا يُغني من الحقِّ شيئًا؛ ولا تقف ما ليس لك به علم؛ قل هاتوا برهانكم إن كنتم صادقين؛ فقل الحقَّ في الدينِ بعلمٍ ودليلٍ ويقين؛ فمن قال بعلمٍ نجا، ومن خرص وظنّ بلا علمٍ لُعِن؛ فاجعل القولَ في الدينِ بالعلمِ والدليلِ دأبك، واحذر الخرصَ والظن."}},{"n":11,"reflection":{"text":"«الذين هم في غمرة ساهون»: الذين هم في غفلةٍ وجهلٍ غامرةٍ لاهون عن الحقِّ والآخرة؛ ففي هذا بيانُ حالِ الغافلين الساهين؛ فاحذر الغفلةَ والسهوَ عن الحقِّ والآخرة، فاستيقظ من الغفلةِ بالتذكّرِ والعمل، فالغمرةُ والسهوُ من صفاتِ الهالكين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستيقاظُ من الغفلة، والحذرُ من السهوِ عن الآخرة."},"action":{"text":"تأمّل حالَ الغافلين: الخرّاصون هم الذين في غمرةٍ، أي غفلةٍ وجهلٍ وضلالةٍ تغمرهم وتغطّيهم، ساهون لاهون غافلون عن الحقِّ والإيمانِ والآخرة، لا يتفكّرون ولا يعتبرون «الذين هم في غمرة ساهون»؛ ففي هذا بيانُ حالِ المكذّبين: أنهم في غمرةٍ من الغفلةِ والجهل، ساهون عن الحقِّ والآخرة؛ فغمرتهم الغفلةُ فسهوا عن الحق؛ فاحذر أنت الغفلةَ والسهوَ عن الحقِّ والآخرة؛ فبل قلوبهم في غمرةٍ من هذا؛ اقترب للناسِ حسابهم وهم في غفلةٍ معرضون؛ فاستيقظ من الغفلةِ بالتذكّرِ والتدبّرِ والعملِ للآخرة؛ ولا تكن من الغافلين؛ فالغمرةُ والسهوُ عن الآخرةِ من صفاتِ الهالكين؛ فمن استيقظ من غفلته واستعدّ نجا، ومن بقي في غمرته وسهوه هلك؛ فاجعل الاستيقاظَ من الغفلةِ والاستعدادَ للآخرةِ دأبك."}},{"n":12,"reflection":{"text":"«يسألون أيان يوم الدين»: يسألون استهزاءً: متى يومُ الجزاء؟ ففي هذا بيانُ استهزائهم بيومِ الدين؛ فلا تسأل عن يومِ الدينِ استهزاءً، بل استعدّ له، فالسؤالُ عنه استهزاءً من الغفلة، فأيقن به واعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ الدين، وتركُ الاستهزاءِ به."},"action":{"text":"تأمّل استهزاءَهم بيومِ الدين: يسأل هؤلاء المكذّبون الغافلون على سبيلِ الاستهزاءِ والاستبعادِ والتكذيب: أيّان، أي متى، يومُ الدينِ والجزاء؟ استبطاءً له وتكذيبًا به «يسألون أيان يوم الدين»؛ ففي هذا بيانُ سؤالِ المكذّبين عن يومِ الدينِ استهزاءً واستبعادًا؛ فسألوا عنه لا استرشادًا بل استهزاءً؛ يستعجلون بها الذين لا يؤمنون بها؛ فلا تسأل أنت عن يومِ الدينِ استهزاءً واستبعادًا؛ بل أيقن به واستعدّ له بالعمل؛ يسألونك عن الساعةِ أيّان مرساها، قل إنما علمها عند ربي؛ فالسؤالُ عن يومِ الدينِ استهزاءً من الغفلةِ والتكذيب؛ فأيقن بيومِ الدينِ واعمل له، ولا تستهزئ به ولا تستبعده؛ فمن أيقن بيومِ الدينِ واستعدّ له نجا، ومن استهزأ به خسر؛ فاجعل اليقينَ بيومِ الدينِ والاستعدادَ له دأبك."}},{"n":13,"reflection":{"text":"«يوم هم على النار يفتنون»: يومَ يُعذّبون ويُحرَقون على النار؛ ففي هذا جوابُ سؤالهم ببيانِ يومِ عذابهم؛ فاحذر يومَ الفتنةِ على النار، فاعمل لتنجو منه، فعذابُ النارِ جزاءُ المكذّبين، فاتّق النارَ بالعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنجاةِ من عذابِ النار، والحذرُ من يومِ الفتنة."},"action":{"text":"تأمّل جوابَ سؤالهم: يومُ الدينِ هو يومَ هم على النارِ يُفتَنون، أي يُعذّبون ويُحرَقون بها، كما يُفتَن الذهبُ بالنارِ ليُختبَر؛ فيُحرَقون بها جزاءَ تكذيبهم «يوم هم على النار يفتنون»؛ ففي هذا جوابُ سؤالهم عن يومِ الدين، ببيانِ أنه يومَ يُعذّبون على النار؛ فيومُ الجزاءِ هو يومُ عذابهم في النار؛ فاحذر أنت يومَ الفتنةِ والعذابِ على النار؛ فاعمل عملًا صالحًا لتنجو منه؛ يومَ يُسحَبون في النارِ على وجوههم ذوقوا مسَّ سقر؛ إنّ الذين كفروا بآياتنا سوف نصليهم نارًا؛ فعذابُ النارِ جزاءُ المكذّبين المستهزئين؛ فاتّق النارَ بالإيمانِ والعملِ الصالحِ والتقوى؛ فمن عمل للنجاةِ من النارِ نجا، ومن أهملها وقع فيها؛ فاجعل العملَ للنجاةِ من عذابِ النارِ دأبك."}},{"n":14,"reflection":{"text":"«ذوقوا فتنتكم هذا الذي كنتم به تستعجلون»: يُقال لهم: ذوقوا عذابكم، هذا الذي كنتم به تستعجلون استهزاءً؛ ففي هذا تقريعُ المستعجلين للعذاب؛ فاحذر الاستهزاءَ والاستعجالَ بالعذاب، فأيقن بالوعيدِ واحذره، فالاستعجالُ بالعذابِ من جهلِ المكذّبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالوعيدِ والحذرُ منه، وتركُ الاستعجالِ به."},"action":{"text":"تأمّل تقريعَ المستعجلين: يُقال للمكذّبين وهم يُعذّبون على النار توبيخًا وتقريعًا: ذوقوا فتنتكم وعذابكم؛ هذا الذي كنتم به في الدنيا تستعجلون استهزاءً وتكذيبًا حين قلتم: متى يومُ الدين؟ «ذوقوا فتنتكم هذا الذي كنتم به تستعجلون»؛ ففي هذا تقريعٌ للمكذّبين الذين استعجلوا العذابَ استهزاءً، فلمّا وقعوا فيه قيل لهم ذوقوه؛ فاستعجلوه فذاقوه؛ فاحذر أنت الاستهزاءَ بالوعيدِ والاستعجالَ بالعذاب؛ ويستعجلونك بالعذابِ ولن يخلف الله وعده؛ فأيقن بالوعيدِ واحذره واستعدّ للنجاةِ منه؛ فالاستعجالُ بالعذابِ والاستهزاءُ به من جهلِ المكذّبين وحمقهم؛ فمن أيقن بالوعيدِ وحذره نجا، ومن استهزأ به واستعجله ذاقه؛ فاجعل اليقينَ بالوعيدِ والحذرَ منه والاستعدادَ للنجاةِ دأبك."}},{"n":15,"reflection":{"text":"«إن المتقين في جنات وعيون»: إنّ المتّقين في بساتينَ وأنهارٍ جارية؛ ففي هذا بيانُ جزاءِ المتّقين؛ فاطلب جنّاتِ المتّقين بالتقوى، فالجنّةُ جزاءُ التقوى، فاعمل بالتقوى لتنالها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ جنّاتِ المتّقين بالتقوى، والعملُ لها."},"action":{"text":"تأمّل جزاءَ المتّقين: إنّ المتّقين الذين اتّقوا الله بفعلِ أوامره واجتنابِ نواهيه، في الآخرةِ في جنّاتٍ وبساتينَ عظيمة، وعيونٍ جاريةٍ متدفّقة؛ فبعد ذكرِ عذابِ المكذّبين، ذكر نعيمَ المتّقين مقابلةً وترغيبًا «إن المتقين في جنات وعيون»؛ ففي هذا بيانُ جزاءِ المتّقين: الجنّاتُ والعيون؛ فجزاؤهم بتقواهم الجنّةُ ونعيمها؛ فاطلب أنت جنّاتِ المتّقين وعيونها بالتقوى؛ فالجنّةُ جزاءُ أهلِ التقوى؛ إنّ للمتّقين مفازًا، حدائقَ وأعنابًا؛ وأزلفتِ الجنّةُ للمتّقين؛ فاعمل بالتقوى، فعلِ المأموراتِ وتركِ المحظورات، لتنال الجنّة؛ فمن اتّقى نال الجنّةَ وعيونها، ومن فرّط حُرِمها؛ فاجعل التقوى سبيلك لنيلِ جنّاتِ المتّقين."}},{"n":16,"reflection":{"text":"«آخذين ما آتاهم ربهم إنهم كانوا قبل ذلك محسنين»: آخذين ما أعطاهم ربّهم راضين، إنهم كانوا قبل ذلك في الدنيا محسنين؛ ففي هذا بيانُ أنّ نعيمَ المتّقين ثمرةُ إحسانهم؛ فأحسن في عملك لتنال جزاءَ المحسنين، فالإحسانُ في الدنيا سببُ النعيمِ في الآخرة، فاجعل الإحسانَ دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العملِ لنيلِ جزاءِ المحسنين."},"action":{"text":"تأمّل أنّ النعيمَ ثمرةُ الإحسان: المتّقون في الجنّةِ آخذين وقابلين ما آتاهم وأعطاهم ربّهم من النعيمِ والكرامةِ راضين به فرحين؛ إنهم كانوا قبل ذلك في الدنيا محسنين في عبادةِ ربّهم وفي معاملةِ خلقه «آخذين ما آتاهم ربهم إنهم كانوا قبل ذلك محسنين»؛ ففي هذا بيانُ أنّ نعيمَ المتّقين في الجنّةِ ثمرةُ إحسانهم في الدنيا؛ فبإحسانهم نالوا النعيم؛ فأحسن أنت في عبادتك لله (بأن تعبده كأنك تراه)، وفي معاملتك للخلقِ (بالبرِّ والإحسان)؛ لتنال جزاءَ المحسنين في الآخرة؛ هل جزاءُ الإحسانِ إلا الإحسان؛ للذين أحسنوا الحسنى وزيادة؛ إنّ الله مع الذين اتّقوا والذين هم محسنون؛ فالإحسانُ في الدنيا سببُ النعيمِ في الآخرة؛ فمن أحسن في الدنيا نال جزاءَ المحسنين، ومن أساء خسر؛ فاجعل الإحسانَ في العبادةِ والمعاملةِ دأبك."}}]},{"title":"صفاتُ المحسنين، وآياتُ الأرضِ والأنفسِ والسماء","range":[17,23],"theme":"صفاتُ المحسنين: قيامُ الليلِ والاستغفارُ بالأسحارِ والإنفاقُ على السائلِ والمحروم، والاستدلالُ بآياتِ الأرضِ والأنفسِ وأنّ في السماءِ الرزقَ وما يوعدون، والقسمُ بربِّ السماءِ والأرضِ إنه لحقٌّ مثلَ ما أنهم ينطقون","verses":[{"n":17,"reflection":{"text":"«كانوا قليلا من الليل ما يهجعون»: كانوا ينامون قليلًا من الليلِ ويقومون للصلاةِ والعبادة؛ ففي هذا بيانُ صفةِ المحسنين بقيامِ الليل؛ فاقتدِ بالمحسنين في قيامِ الليلِ والتهجّد، فقيامُ الليلِ من صفاتِ المحسنين، فأحيِ جزءًا من ليلك بالعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحياءُ الليلِ بالعبادةِ والتهجّد، اقتداءً بالمحسنين."},"action":{"text":"تأمّل صفةَ المحسنين بقيامِ الليل: كان المتّقون المحسنون ينامون قليلًا من الليل، ويقومون أكثره للصلاةِ والتهجّدِ والذكرِ والدعاء؛ فكانوا قليلًا من الليلِ ما يهجعون، أي ما ينامون «كانوا قليلا من الليل ما يهجعون»؛ ففي هذا بيانُ أنّ من صفاتِ المحسنين قيامَ الليلِ وقلّةَ النوم؛ فأحيوا لياليهم بالعبادةِ والتهجّد؛ فاقتدِ أنت بالمحسنين في قيامِ الليلِ والتهجّد؛ تتجافى جنوبهم عن المضاجعِ يدعون ربّهم خوفًا وطمعًا؛ ومن الليلِ فتهجّد به نافلةً لك؛ والمستغفرين بالأسحار؛ أمّن هو قانتٌ آناءَ الليلِ ساجدًا وقائمًا؛ فقيامُ الليلِ دأبُ الصالحين وشرفُ المؤمن؛ فأحيِ جزءًا من ليلك بالصلاةِ والذكرِ والدعاء؛ فمن قام الليلَ نال شرفَ القربِ والإحسان، ومن نام عنه فاته خير؛ فاجعل إحياءَ جزءٍ من ليلك بالعبادةِ اقتداءً بالمحسنين دأبك."}},{"n":18,"reflection":{"text":"«وبالأسحار هم يستغفرون»، وفي أواخرِ الليلِ (الأسحار) هم يستغفرون الله؛ ففي هذا بيانُ صفةِ المحسنين بالاستغفارِ في الأسحار؛ فاستغفر الله في الأسحارِ وقتَ النزولِ الإلهي، فالاستغفارُ في السحرِ من صفاتِ المحسنين، فاجعله دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستغفارُ في الأسحار، اقتداءً بالمحسنين."},"action":{"text":"تأمّل صفةَ المحسنين بالاستغفار: وكان المتّقون المحسنون في الأسحار، وهي أواخرُ الليلِ قبيلَ الفجر، يستغفرون الله ويطلبون مغفرته، بعد قيامهم وتهجّدهم؛ فختموا قيامهم بالاستغفار «وبالأسحار هم يستغفرون»؛ ففي هذا بيانُ أنّ من صفاتِ المحسنين الاستغفارَ في الأسحار؛ فمع قيامهم الليل، يختمونه بالاستغفارِ في السحر؛ فاستغفر أنت الله في الأسحارِ وقتَ النزولِ الإلهيِّ وإجابةِ الدعاء؛ ينزل ربّنا كلَّ ليلةٍ إلى السماءِ الدنيا حين يبقى ثلثُ الليلِ الآخر، فيقول هل من مستغفرٍ فأغفر له؛ والمستغفرين بالأسحار؛ وبالأسحارِ هم يستغفرون؛ فالاستغفارُ في السحرِ من أعظمِ العباداتِ وأرجاها للإجابة؛ فاجعل الاستغفارَ في الأسحارِ اقتداءً بالمحسنين دأبك؛ فبالاستغفارِ في السحرِ تُنال المغفرةُ والقرب."}},{"n":19,"reflection":{"text":"«وفي أموالهم حق للسائل والمحروم»، وفي أموالهم نصيبٌ معلومٌ للسائلِ (الذي يسأل) والمحروم (المتعفّفِ الذي لا يسأل)؛ ففي هذا بيانُ صفةِ المحسنين بالإنفاق؛ فأنفق من مالك على السائلِ والمحروم، فالإنفاقُ على المحتاجين من صفاتِ المحسنين، فاجعل لمالك حقًّا للمحتاجين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ على السائلِ والمحروم، اقتداءً بالمحسنين."},"action":{"text":"تأمّل صفةَ المحسنين بالإنفاق: وكان في أموالِ المتّقين المحسنين حقٌّ ونصيبٌ يجعلونه للسائلِ الذي يسأل ويتعرّض، والمحرومِ المتعفّفِ الذي لا يسأل فيُحسَب غنيًّا فيُحرَم؛ فيعطونهما من أموالهم «وفي أموالهم حق للسائل والمحروم»؛ ففي هذا بيانُ أنّ من صفاتِ المحسنين الإنفاقَ على المحتاجين: السائلِ والمحروم؛ فجعلوا في أموالهم حقًّا للفقراء؛ فأنفق أنت من مالك على السائلِ المحتاجِ والمحرومِ المتعفّف؛ والذين في أموالهم حقٌّ معلوم، للسائلِ والمحروم؛ وآتى المالَ على حبّه ذوي القربى واليتامى والمساكين؛ للفقراءِ الذين أُحصِروا في سبيلِ الله... يحسبهم الجاهلُ أغنياءَ من التعفّف؛ فالإنفاقُ على المحتاجين من صفاتِ المحسنين وأسبابِ النعيم؛ فمن أنفق على المحتاجين نال جزاءَ المحسنين، ومن بخل حُرِم؛ فاجعل الإنفاقَ على السائلِ والمحرومِ من مالك دأبك."}},{"n":20,"reflection":{"text":"«وفي الأرض آيات للموقنين»، وفي الأرضِ آياتٌ ودلالاتٌ على قدرةِ الله لأهلِ اليقين؛ ففي هذا الاستدلالُ بآياتِ الأرض؛ فتأمّل آياتِ الله في الأرضِ لتزداد يقينًا، فالأرضُ مليئةٌ بآياتِ الله، فتفكّر فيها لتوقن بربّك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آياتِ الأرضِ للوصولِ إلى اليقين."},"action":{"text":"تأمّل الاستدلالَ بآياتِ الأرض: وفي الأرضِ آياتٌ ودلالاتٌ كثيرةٌ على قدرةِ الله ووحدانيته وحكمته: من الجبالِ والبحارِ والأنهارِ والأشجارِ والثمارِ والمعادنِ واختلافِ ألوانها وطعومها؛ لكن ينتفع بها الموقنون الذين يطلبون اليقين «وفي الأرض آيات للموقنين»؛ ففي هذا الاستدلالُ بآياتِ الأرضِ على قدرةِ الله، وأنّ المنتفعَ بها أهلُ اليقين؛ فالأرضُ مليئةٌ بآياتِ الله؛ فتأمّل أنت آياتِ الله في الأرض: في تنوّعها وعجائبها ومنافعها؛ وفي الأرضِ قطعٌ متجاوراتٌ وجنّاتٌ من أعناب؛ ومن آياته أنك ترى الأرضَ خاشعة؛ أفلا ينظرون إلى الأرضِ كيف سُطِحت؛ فبالتفكّرِ في آياتِ الأرضِ تزداد يقينًا بالخالقِ ووحدانيته؛ فمن تفكّر في آياتِ الأرضِ أيقن، ومن أعرض بقي في غفلته؛ فاجعل التفكّرَ في آياتِ الأرضِ سبيلَ يقينك بربّك."}},{"n":21,"reflection":{"text":"«وفي أنفسكم أفلا تبصرون»، وفي أنفسِكم آياتٌ عظيمة، أفلا تبصرون فتعتبرون؟ ففي هذا الاستدلالُ بآياتِ النفس؛ فتأمّل آياتِ الله في نفسك: في خلقك وتركيبك وأعضائك وحواسّك، فأنت آيةٌ ناطقة، فتفكّر في نفسك لتوقن بخالقك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آياتِ النفسِ للاعتبارِ واليقين."},"action":{"text":"تأمّل الاستدلالَ بآياتِ النفس: وفي أنفسِكم، أيها الناس، آياتٌ ودلالاتٌ عظيمةٌ على قدرةِ الله وحكمته: في خلقكم من نطفةٍ، وتركيبِ أبدانكم، وحواسّكم، وعقولكم، وما أودع فيكم من العجائب؛ أفلا تبصرون هذه الآياتِ فتعتبرون بها؟ «وفي أنفسكم أفلا تبصرون»؛ ففي هذا الاستدلالُ بآياتِ النفسِ على قدرةِ الله، والحثُّ على التبصّرِ فيها؛ فأنت آيةٌ في نفسك دالّةٌ على خالقك؛ فتأمّل أنت آياتِ الله في نفسك: في خلقك وتصويرك وأعضائك وحواسّك وعقلك؛ سنريهم آياتنا في الآفاقِ وفي أنفسهم؛ لقد خلقنا الإنسانَ في أحسنِ تقويم؛ يا أيها الإنسانُ ما غرّك بربّك الكريم، الذي خلقك فسوّاك فعدلك؛ فمن تفكّر في خلقِ نفسه أبصر قدرةَ الله وأيقن به؛ فمن أبصر آياتِ نفسه اعتبر وآمن، ومن غفل عنها ضلّ؛ فاجعل التفكّرَ في آياتِ نفسك سبيلَ يقينك بخالقك."}},{"n":22,"reflection":{"text":"«وفي السماء رزقكم وما توعدون»، وفي السماءِ رزقكم (المطرُ وأسبابُ الرزق) وما توعدون من الخيرِ والشرّ؛ ففي هذا بيانُ أنّ الرزقَ من الله من السماء؛ فاطلب رزقك من الله الذي جعله في السماء، وثق بأنّ رزقك مكتوبٌ عنده، فالرزقُ بيدِ الله، فتوكّل عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الرزقِ من الله والتوكّلُ عليه، وإدراكُ أنه بيده."},"action":{"text":"تأمّل أنّ الرزقَ من الله: وفي السماءِ رزقكم، أي أسبابُ رزقكم من المطرِ الذي به حياةُ الأرضِ والنبات، أو رزقكم مكتوبٌ ومقدّرٌ في السماء؛ وما توعدون من الخيرِ والشرِّ والثوابِ والعقاب «وفي السماء رزقكم وما توعدون»؛ ففي هذا بيانُ أنّ رزقَ العبادِ من الله، وأنّ أسبابه تنزل من السماء، وأنّ ما وُعِدوا به مقدّرٌ عند الله؛ فالرزقُ بيدِ الله ومن عنده؛ فاطلب أنت رزقك من الله الذي جعل أسبابه في السماء؛ وما من دابّةٍ في الأرضِ إلا على الله رزقها؛ وفي السماءِ رزقكم؛ إنّ الله هو الرزّاقُ ذو القوّةِ المتين؛ وثق بأنّ رزقك مكتوبٌ مقدّرٌ عند الله سيأتيك؛ فاتّقوا الله وأجملوا في الطلب؛ فالرزقُ بيدِ الله وحده يقسمه بحكمته؛ فمن طلب الرزقَ من الله وتوكّل عليه كُفِي، ومن اعتمد على غيره خُذِل؛ فاجعل طلبَ الرزقِ من الله والتوكّلَ عليه دأبك."}},{"n":23,"reflection":{"text":"«فورب السماء والأرض إنه لحق مثل ما أنكم تنطقون»: فوربِّ السماءِ والأرض، إنّ ما وُعِدتم به لحقٌّ كما أنكم تنطقون؛ ففي هذا تأكيدُ صدقِ الوعدِ بأبلغِ قسم؛ فأيقن بصدقِ وعدِ الله وحقيّته كما توقن بنطقك، فما وعد الله به حقٌّ لا شكَّ فيه، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدقِ وعدِ الله وحقيّته، كاليقينِ بالمحسوس."},"action":{"text":"تأمّل تأكيدَ صدقِ الوعد: فوربِّ السماءِ والأرض، أقسم الله بنفسه: إنّ ما وُعِدتم به من البعثِ والرزقِ والجزاءِ لحقٌّ ثابتٌ لا شكَّ فيه، مثلَ ما أنكم تنطقون، أي بقدرِ يقينكم بنطقكم الذي لا تشكّون فيه «فورب السماء والأرض إنه لحق مثل ما أنكم تنطقون»؛ ففي هذا تأكيدُ صدقِ وعدِ الله بأبلغِ قسمٍ وأوضحِ تشبيه؛ فشبّه اليقينَ بصدقِ الوعدِ باليقينِ بنطقِ الإنسانِ الذي لا يشكّ فيه؛ فكما لا تشكّ في نطقك، فلا تشكّ في وعدِ الله؛ فأيقن أنت بصدقِ وعدِ الله وحقيّته يقينًا جازمًا كيقينك بالمحسوسِ الذي تراه وتنطق به؛ فما وعد الله به حقٌّ لا ريب فيه؛ ومن أصدقُ من الله حديثًا؛ فاعمل لما وعد الله به من البعثِ والجزاء؛ فمن أيقن بصدقِ الوعدِ عمل له، ومن شكّ فيه غفل؛ فاجعل يقينك بصدقِ وعدِ الله كيقينك بالمحسوسِ دأبك."}}]},{"title":"ضيفُ إبراهيمَ المكرمون والبشارةُ بالولد","range":[24,30],"theme":"قصةُ ضيفِ إبراهيمَ المكرمين حين دخلوا فسلّموا وردَّ بأحسنَ منه، وإكرامُه لهم بالعجلِ السمينِ وعرضِه بلطف، وخوفُه منهم لمّا لم يأكلوا وتطمينُهم له وبشارتُهم بغلامٍ عليم، وتعجّبُ امرأته العجوزِ العقيمِ وتقريرُهم أنه قولُ ربّه الحكيمِ العليم","verses":[{"n":24,"reflection":{"text":"«هل أتاك حديث ضيف إبراهيم المكرمين»: هل بلغك، يا محمدُ، خبرُ ضيفِ إبراهيمَ المكرمين (الملائكة)؟ ففي هذا تشويقٌ لقصةِ ضيفِ إبراهيم؛ فتأمّل قصةَ إبراهيمَ وإكرامه لضيفه، واقتدِ به في إكرامِ الضيف، فإكرامُ الضيفِ من خلقِ الأنبياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بإبراهيمَ في إكرامِ الضيف، والتأمّلُ في قصصِ الأنبياء."},"action":{"text":"تأمّل تشويقَ قصةِ الضيف: هل أتاك، يا محمدُ، وبلغك حديثُ وخبرُ ضيفِ إبراهيمَ عليه السلام المكرمين، وهم الملائكةُ الذين أكرمهم إبراهيمُ، أو المكرمون عند الله «هل أتاك حديث ضيف إبراهيم المكرمين»؛ ففي هذا تشويقٌ وتنبيهٌ لقصةِ ضيفِ إبراهيمَ وما فيها من العبر؛ فبدأ القصةَ بالاستفهامِ التشويقيِّ لتنبيهِ السامع؛ فتأمّل أنت قصةَ إبراهيمَ عليه السلام مع ضيفه، وإكرامه لهم؛ واقتدِ به في إكرامِ الضيفِ وحسنِ الضيافة؛ من كان يؤمن بالله واليومِ الآخرِ فليكرم ضيفه؛ فإكرامُ الضيفِ من خلقِ الأنبياءِ وسنّةِ إبراهيمَ أبي الأضياف؛ وتأمّل قصصَ الأنبياءِ لتعتبر وتقتدي؛ لقد كان في قصصهم عبرةٌ لأولي الألباب؛ فمن اقتدى بالأنبياءِ في أخلاقهم اهتدى؛ فاجعل الاقتداءَ بإبراهيمَ في إكرامِ الضيفِ والتأمّلَ في قصصِ الأنبياءِ دأبك."}},{"n":25,"reflection":{"text":"«إذ دخلوا عليه فقالوا سلاما قال سلام قوم منكرون»: حين دخل الملائكةُ على إبراهيمَ فقالوا: سلامًا، قال: سلامٌ، أنتم قومٌ غيرُ معروفين؛ ففي هذا بيانُ ردِّ السلامِ بأحسنَ منه؛ فردَّ السلامَ بأحسنَ منه كما فعل إبراهيم، فإفشاءُ السلامِ وردُّه بأحسنَ منه من الأدب، فاجعله دأبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفشاءُ السلامِ وردُّه بأحسنَ منه، اقتداءً بإبراهيم."},"action":{"text":"تأمّل أدبَ ردِّ السلام: اذكر حين دخل الملائكةُ (في صورةِ رجال) على إبراهيمَ، فقالوا: سلامًا؛ قال إبراهيمُ: سلامٌ عليكم، فردَّ بالجملةِ الاسميةِ الدالّةِ على الثبوتِ والدوام، وهي أبلغُ من تحيّتهم؛ وقال في نفسه: هؤلاء قومٌ منكرون غيرُ معروفين لي «إذ دخلوا عليه فقالوا سلاما قال سلام قوم منكرون»؛ ففي هذا بيانُ أدبِ إبراهيمَ في ردِّ السلامِ بأحسنَ منه؛ فردَّ التحيّةَ بأحسنَ منها؛ فاجعل أنت إفشاءَ السلامِ وردَّه بأحسنَ منه دأبك؛ وإذا حُيّيتم بتحيّةٍ فحيّوا بأحسنَ منها أو ردّوها؛ أفشوا السلامَ بينكم؛ لا تدخلون الجنّةَ حتى تؤمنوا، ولا تؤمنوا حتى تحابّوا، أفلا أدلّكم على شيءٍ إذا فعلتموه تحاببتم: أفشوا السلامَ بينكم؛ فإفشاءُ السلامِ وردُّه بأحسنَ منه من الأدبِ الجالبِ للمحبّة؛ فمن أفشى السلامَ وردَّه بأحسنَ منه نال المحبّةَ والأجر؛ فاجعل إفشاءَ السلامِ وحسنَ ردِّه اقتداءً بإبراهيمَ دأبك."}},{"n":26,"reflection":{"text":"«فراغ إلى أهله فجاء بعجل سمين»: فذهب إبراهيمُ إلى أهله خفيةً فجاء بعجلٍ سمينٍ مشويّ؛ ففي هذا بيانُ حسنِ الضيافةِ وتعجيلِ القرى؛ فأكرم ضيفك وعجّل قراه بأطيبِ ما تجد كما فعل إبراهيم، فحسنُ الضيافةِ من خلقِ الكرام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حسنُ الضيافةِ وتعجيلُ القرى بأطيبِ الموجود."},"action":{"text":"تأمّل حسنَ ضيافةِ إبراهيم: فراغ إبراهيمُ، أي ذهب في خفيةٍ وسرعةٍ، إلى أهله، فجاء بعجلٍ سمينٍ مشويٍّ كاملٍ من خيارِ ماله؛ فأتى بأطيبِ ما عنده بسرعةٍ وسخاء «فراغ إلى أهله فجاء بعجل سمين»؛ ففي هذا بيانُ كمالِ ضيافةِ إبراهيمَ وحسنها وسرعتها؛ فذهب سرًّا لئلا يمنعوه، وأتى بأطيبِ الطعامِ وأسمنه بسرعة؛ فاجعل أنت حسنَ الضيافةِ وتعجيلَ القرى بأطيبِ ما تجد دأبك كإبراهيم؛ فأتى بالعجلِ السمينِ كاملًا لا بعضه، وبسرعةٍ لا تباطؤ؛ من كان يؤمن بالله واليومِ الآخرِ فليكرم ضيفه؛ فحسنُ الضيافةِ وإكرامُ الضيفِ من خلقِ الكرامِ وسنّةِ الأنبياء؛ الضيافةُ ثلاثةُ أيام؛ فمن أكرم ضيفه وعجّل قراه بأطيبِ ما يجد نال الأجرَ والمحبّة؛ فاجعل حسنَ الضيافةِ وتعجيلَ القرى بأطيبِ الموجودِ دأبك."}},{"n":27,"reflection":{"text":"«فقربه إليهم قال ألا تأكلون»: فقرّب العجلَ إليهم وعرضه عليهم قائلًا بلطف: ألا تأكلون؟ ففي هذا بيانُ لطفِ العرضِ في الضيافة؛ فاعرض الطعامَ على ضيفك بلطفٍ وترغيبٍ كما فعل إبراهيم، فحسنُ العرضِ من تمامِ الضيافة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لطفُ العرضِ في الضيافة، وحسنُ ملاطفةِ الضيف."},"action":{"text":"تأمّل لطفَ العرضِ في الضيافة: فقرّب إبراهيمُ العجلَ السمينَ إلى ضيوفه، ووضعه بين أيديهم؛ وعرضه عليهم بلطفٍ وأدبٍ وترغيب، قائلًا: ألا تأكلون؟ تلطّفًا في الدعوةِ إلى الطعام «فقربه إليهم قال ألا تأكلون»؛ ففي هذا بيانُ لطفِ إبراهيمَ في عرضِ الطعامِ على ضيوفه؛ فقرّبه إليهم ولم يقل لهم تقدّموا؛ وعرضه بلطفٍ وأدب: ألا تأكلون؟ ولم يأمرهم أمرًا؛ فاجعل أنت لطفَ العرضِ وحسنَ الملاطفةِ في ضيافتك دأبك؛ فقرّب الطعامَ إلى ضيفك، واعرضه بلطفٍ وترغيبٍ وأدب؛ فحسنُ العرضِ والملاطفةِ من تمامِ الضيافةِ وكمالها؛ فالكلماتُ الطيّبةُ اللطيفةُ صدقة؛ فمن أحسن عرضَ الطعامِ وملاطفةَ ضيفه نال تمامَ أجرِ الضيافة؛ فاجعل لطفَ العرضِ وحسنَ ملاطفةِ الضيفِ في ضيافتك دأبك."}},{"n":28,"reflection":{"text":"«فأوجس منهم خيفة قالوا لا تخف وبشروه بغلام عليم»: فأحسّ إبراهيمُ في نفسه خوفًا منهم (لمّا لم يأكلوا)، قالوا: لا تخف، وبشّروه بغلامٍ عليمٍ (إسحاق)؛ ففي هذا بيانُ بشارةِ إبراهيمَ بالولد؛ فاعلم أنّ الله يبشّر أولياءه بالخيرِ ويطمئنهم، فثق بلطفِ الله وبشراه، وارجُ فضله ولو بعد يأس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بلطفِ الله وبشراه، ورجاءُ فضله ولو بعد يأس."},"action":{"text":"تأمّل بشارةَ إبراهيمَ بالولد: فلمّا رأى إبراهيمُ أيديَهم لا تصل إلى الطعامِ ولا يأكلون، أوجس وأحسّ في نفسه منهم خيفةً وأنكرهم؛ فقالوا مطمئنين له: لا تخف، إنا رسلُ ربّك؛ وبشّروه بغلامٍ عليمٍ حليمٍ، وهو إسحاقُ عليه السلام «فأوجس منهم خيفة قالوا لا تخف وبشروه بغلام عليم»؛ ففي هذا بيانُ خوفِ إبراهيمَ ثم تطمينِ الملائكةِ له، وبشارتِه بالولدِ العليم؛ فطمأنوه ثم بشّروه بالخير؛ فاعلم أنت أنّ الله يبشّر أولياءه بالخيرِ ويطمئن قلوبهم عند الخوف؛ إنّ الذين قالوا ربّنا الله ثم استقاموا تتنزّل عليهم الملائكةُ ألا تخافوا ولا تحزنوا وأبشروا بالجنّة؛ فثق بلطفِ الله وبشراه لأوليائه؛ وارجُ فضلَ الله وكرمه ولو بعد يأسٍ من الأسباب؛ فقد بُشِّر إبراهيمُ بالولدِ في كبره؛ ومن يقنط من رحمةِ ربّه إلا الضالّون؛ فمن وثق بلطفِ الله ورجا فضله نال البشرى، ومن يئس خسر؛ فاجعل الثقةَ بلطفِ الله ورجاءَ فضله دأبك."}},{"n":29,"reflection":{"text":"«فأقبلت امرأته في صرة فصكت وجهها وقالت عجوز عقيم»: فأقبلت امرأةُ إبراهيمَ (سارة) في صيحةٍ وصرخةٍ من الفرحِ والعجب، فضربت وجهها وقالت: أنا عجوزٌ عقيمٌ كيف ألد؟ ففي هذا بيانُ تعجّبها من البشارة؛ فاعلم أنّ فضلَ الله لا يحدّه سببٌ ولا عادة، فلا تستبعد فضلَ الله ولو خالف العادة، فقدرةُ الله فوق الأسباب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ استبعادِ فضلِ الله ولو خالف العادة، وإدراكُ أنّ قدرته فوق الأسباب."},"action":{"text":"تأمّل تعجّبَ سارة: فأقبلت امرأةُ إبراهيمَ (سارة) لمّا سمعت البشارةَ في صرّةٍ، أي صيحةٍ وصرخةٍ من الفرحِ والتعجّب؛ فصكّت وجهها، أي ضربته بيدها تعجّبًا، كعادةِ النساء؛ وقالت متعجّبةً: أنا عجوزٌ كبيرةٌ عقيمٌ لا ألد، فكيف ألد؟ «فأقبلت امرأته في صرة فصكت وجهها وقالت عجوز عقيم»؛ ففي هذا بيانُ تعجّبِ سارة من البشارةِ بالولدِ مع كبرها وعقمها؛ فاستبعدت الولادةَ لمخالفتها العادة؛ فاعلم أنت أنّ فضلَ الله وقدرته لا يحدّهما سببٌ ولا عادة؛ فالله قادرٌ على خرقِ العادةِ وإيجادِ الولدِ من العجوزِ العقيم؛ قالوا أتعجبين من أمرِ الله، رحمةُ الله وبركاته عليكم أهلَ البيت؛ فلا تستبعد أنت فضلَ الله وقدرته ولو خالفا العادةَ والأسباب؛ إنّ الله على كلِّ شيءٍ قدير؛ فقدرةُ الله فوق الأسبابِ والعادات؛ فمن أيقن بقدرةِ الله فوق الأسبابِ رجا فضله، ومن حصر قدرته في العادةِ استبعد؛ فاجعل عدمَ استبعادِ فضلِ الله ولو خالف العادةَ دأبك."}},{"n":30,"reflection":{"text":"«قالوا كذلك قال ربك إنه هو الحكيم العليم»: قال الملائكة: كذلك قال ربّك، إنه هو الحكيمُ العليم؛ ففي هذا تقريرُ أنّ ما أخبر الله به واقعٌ بحكمته وعلمه؛ فسلّم لخبرِ الله وحكمته وعلمه، فما قدّره الله بحكمةٍ وعلم، فما قاله الله واقعٌ لا محالة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لخبرِ الله وحكمته وعلمه، واليقينُ بوقوعِ ما أخبر به."},"action":{"text":"تأمّل تقريرَ حكمةِ الله وعلمه: قالت الملائكةُ لسارة مؤكّدين البشارة: كذلك، أي كما بشّرناك، قال ربّك، وأخبر بولادتك؛ إنه هو الحكيمُ الذي يضع الأشياءَ مواضعها بحكمته، العليمُ الذي أحاط علمه بكلِّ شيء، ومنه هذا الأمر «قالوا كذلك قال ربك إنه هو الحكيم العليم»؛ ففي هذا تقريرُ أنّ ما أخبر الله به من البشارةِ واقعٌ لا محالة، لأنه صادرٌ عن حكمته وعلمه؛ فما قاله الله حقٌّ واقعٌ بحكمته وعلمه؛ فسلّم أنت لخبرِ الله ووعده، واعلم أنه واقعٌ بحكمته وعلمه؛ فما أخبر الله به أو وعد به واقعٌ لا محالة؛ إنّ الله لا يخلف الميعاد؛ فما قدّره الله وأخبر به فبحكمةٍ بالغةٍ وعلمٍ محيط؛ وهو الحكيمُ الخبير؛ وكان الله عليمًا حكيمًا؛ فسلّم لحكمةِ الله وعلمه فيما يقدّره ويخبر به؛ فمن سلّم لحكمةِ الله وعلمه اطمأنّ، ومن اعترض تعب؛ فاجعل التسليمَ لخبرِ الله وحكمته وعلمه دأبك."}}]},{"title":"قومُ لوطٍ وإهلاكُهم، ونجاةُ المؤمنين","range":[31,37],"theme":"سؤالُ إبراهيمَ الملائكةَ عن مهمّتهم فأخبروه بإرسالهم إلى قومٍ مجرمين لإرسالِ حجارةٍ من طينٍ مسوّمةٍ للمسرفين، وإخراجِ المؤمنين ولم يوجد فيها غيرُ بيتٍ من المسلمين، وتركِ آيةً للذين يخافون العذابَ الأليم","verses":[{"n":31,"reflection":{"text":"«قال فما خطبكم أيها المرسلون»: قال إبراهيمُ للملائكة: فما شأنكم وأمركم الذي جئتم له أيها المرسلون؟ ففي هذا بيانُ سؤالِ إبراهيمَ عن مهمّتهم؛ فتعلّم من إبراهيمَ حسنَ السؤالِ والاهتمامَ بأمرِ الله، فالسؤالُ عن الحقِّ وأمرِ الله من العلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاهتمامُ بأمرِ الله وحسنُ السؤالِ عنه."},"action":{"text":"تأمّل سؤالَ إبراهيم: قال إبراهيمُ للملائكةِ لمّا علم أنهم رسلٌ من الله: فما خطبكم، أي ما شأنكم العظيمُ وأمركم الذي أُرسِلتم له، أيها المرسلون؟ استفهامًا عن مهمّتهم «قال فما خطبكم أيها المرسلون»؛ ففي هذا بيانُ سؤالِ إبراهيمَ عن مهمّةِ الملائكةِ واهتمامِه بأمرِ الله؛ فلمّا علم أنهم رسلٌ سألهم عن مهمّتهم؛ فتعلّم أنت من إبراهيمَ الاهتمامَ بأمرِ الله وحسنَ السؤالِ عنه؛ فالسؤالُ عن الحقِّ والعلمِ وأمرِ الله من الخير؛ فاسألوا أهلَ الذكرِ إن كنتم لا تعلمون؛ فمن اهتمّ بأمرِ الله وسأل عنه ازداد علمًا، ومن أعرض بقي في جهله؛ فاجعل الاهتمامَ بأمرِ الله وحسنَ السؤالِ عنه دأبك."}},{"n":32,"reflection":{"text":"«قالوا إنا أرسلنا إلى قوم مجرمين»: قالوا: إنا أُرسِلنا إلى قومٍ مجرمين (قومِ لوط) لإهلاكهم؛ ففي هذا بيانُ مهمّةِ الملائكةِ بإهلاكِ المجرمين؛ فاحذر الإجرامَ الذي يوجب الهلاك، فاجتنب الفواحشَ والمعاصي، فالإجرامُ سببُ نزولِ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الإجرامِ والفواحش، والحذرُ من عاقبته."},"action":{"text":"تأمّل مهمّةَ الملائكة: قالت الملائكةُ لإبراهيم: إنا أُرسِلنا إلى قومٍ مجرمين، وهم قومُ لوطٍ الذين أجرموا بارتكابِ الفاحشةِ والكفر، لإهلاكهم وعقوبتهم «قالوا إنا أرسلنا إلى قوم مجرمين»؛ ففي هذا بيانُ أنّ مهمّةَ الملائكةِ إهلاكُ القومِ المجرمين؛ فأُرسِلوا لعذابِ المجرمين جزاءَ إجرامهم؛ فاحذر أنت الإجرامَ والفواحشَ والمعاصيَ التي توجب الهلاك؛ فقومُ لوطٍ أُهلِكوا بإجرامهم وفاحشتهم؛ إنّ المجرمين في ضلالٍ وسعر؛ فأخذناهم بذنوبهم؛ فاجتنب الفواحشَ ما ظهر منها وما بطن، والمعاصيَ والكبائر؛ فالإجرامُ والإصرارُ على الفواحشِ سببُ نزولِ العذاب؛ فمن اجتنب الإجرامَ نجا، ومن أجرم هلك؛ فاجعل اجتنابَ الإجرامِ والفواحشِ والمعاصي دأبك."}},{"n":33,"reflection":{"text":"«لنرسل عليهم حجارة من طين»: لنرسل عليهم حجارةً من طينٍ مطبوخٍ (سِجّيل)؛ ففي هذا بيانُ نوعِ عذابِ قومِ لوط؛ فاعتبر بعذابِ قومِ لوطٍ بالحجارة، فالفاحشةُ توجب أشدَّ العذاب، فاحذرها لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعذابِ الفاحشة، والحذرُ منها."},"action":{"text":"تأمّل نوعَ عذابِ قومِ لوط: أُرسِلنا لنرسل على قومِ لوطٍ المجرمين حجارةً من طينٍ متحجّرٍ مطبوخٍ (سِجّيل)، عقوبةً لهم على فاحشتهم وكفرهم «لنرسل عليهم حجارة من طين»؛ ففي هذا بيانُ نوعِ العذابِ الذي أُرسِلت به الملائكةُ لقومِ لوط: الحجارةُ من الطينِ المتحجّر؛ فعُذّبوا بقلبِ ديارهم وإمطارِ الحجارة؛ فاعتبر أنت بعذابِ قومِ لوطٍ بالحجارةِ جزاءَ فاحشتهم؛ فأمطرنا عليهم حجارةً من سِجّيلٍ منضود، مسوّمةً عند ربّك؛ فجعلنا عاليها سافلها وأمطرنا عليهم حجارةً من سِجّيل؛ فالفاحشةُ توجب أشدَّ العذابِ وأنكاه؛ فاحذر الفاحشةَ وأسبابها لتنجو من العذاب؛ فمن اجتنب الفاحشةَ نجا، ومن ارتكبها استحقّ العذاب؛ فاجعل الاعتبارَ بعذابِ الفاحشةِ والحذرَ منها دأبك."}},{"n":34,"reflection":{"text":"«مسومة عند ربك للمسرفين»: تلك الحجارةُ معلَّمةٌ مكتوبةٌ عند ربّك للمسرفين المتجاوزين الحدّ؛ ففي هذا بيانُ أنّ العذابَ مقدّرٌ للمسرفين؛ فاحذر الإسرافَ في المعاصي وتجاوزَ الحدود، فالإسرافُ في المعاصي يوجب العذابَ المقدّر، فالزم حدودَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ حدودِ الله، والحذرُ من الإسرافِ في المعاصي."},"action":{"text":"تأمّل أنّ العذابَ للمسرفين: تلك الحجارةُ مسوّمةٌ، أي معلَّمةٌ مُعَدّةٌ مكتوبٌ على كلِّ حجرٍ اسمُ من يقع عليه، عند ربّك، للمسرفين المتجاوزين حدودَ الله في الكفرِ والفواحشِ والمعاصي «مسومة عند ربك للمسرفين»؛ ففي هذا بيانُ أنّ ذلك العذابَ مقدّرٌ معلَّمٌ عند الله للمسرفين المتجاوزين الحدّ؛ فالعذابُ مُعَدٌّ لأهله من المسرفين؛ فاحذر أنت الإسرافَ في المعاصي وتجاوزَ حدودِ الله؛ فالإسرافُ في المعاصي والفواحشِ يوجب العذابَ المقدّر؛ وأنّ المسرفين هم أصحابُ النار؛ ولا تطيعوا أمرَ المسرفين؛ فالزم حدودَ الله ولا تتجاوزها؛ تلك حدودُ الله فلا تعتدوها؛ فمن لزم حدودَ الله نجا، ومن أسرف وتجاوزها هلك؛ فاجعل لزومَ حدودِ الله واجتنابَ الإسرافِ في المعاصي دأبك."}},{"n":35,"reflection":{"text":"«فأخرجنا من كان فيها من المؤمنين»: فأخرجنا من كان في قريةِ قومِ لوطٍ من المؤمنين قبل العذاب؛ ففي هذا بيانُ نجاةِ المؤمنين؛ فاعلم أنّ الله ينجّي المؤمنين من العذاب، فآمن لتكون من الناجين، فالإيمانُ سببُ النجاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ سبيلُ النجاة، وإدراكُ أنّ الله ينجّي المؤمنين."},"action":{"text":"تأمّل نجاةَ المؤمنين: فأخرجنا وأنجينا من كان في قريةِ قومِ لوطٍ من المؤمنين قبل نزولِ العذاب، لئلا يصيبهم ما أصاب المجرمين «فأخرجنا من كان فيها من المؤمنين»؛ ففي هذا بيانُ أنّ الله أنجى المؤمنين من قومِ لوطٍ قبل العذاب؛ فميّزهم عن المجرمين وأنجاهم؛ فاعلم أنت أنّ الله ينجّي المؤمنين من العذابِ والهلاك؛ فنجّيناه وأهله إلا امرأته؛ ثم ننجّي رسلنا والذين آمنوا كذلك حقًّا علينا نُنجِ المؤمنين؛ فالإيمانُ سببُ النجاةِ من العذاب؛ فآمن أنت بالله إيمانًا صادقًا لتكون من الناجين؛ فمن آمن نجا، ومن كفر وأجرم هلك؛ فاجعل الإيمانَ الصادقَ سبيلَ نجاتك من العذاب."}},{"n":36,"reflection":{"text":"«فما وجدنا فيها غير بيت من المسلمين»: فما وجدنا في قريةِ قومِ لوطٍ غيرَ بيتٍ واحدٍ من المسلمين (بيتِ لوط)؛ ففي هذا بيانُ قلّةِ المؤمنين حينها؛ فلا يهمّنك قلّةُ أهلِ الحقّ، فالعبرةُ بالإيمانِ لا بالكثرة، فكن مع الحقِّ ولو قلَّ أهله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ مع الحقِّ ولو قلَّ أهله، وعدمُ الاغترارِ بالكثرة."},"action":{"text":"تأمّل قلّةَ المؤمنين: فما وجدنا في قريةِ قومِ لوطٍ غيرَ بيتٍ واحدٍ من المسلمين المؤمنين، وهو بيتُ لوطٍ عليه السلام؛ فكان المؤمنون فيهم قلّةً «فما وجدنا فيها غير بيت من المسلمين»؛ ففي هذا بيانُ قلّةِ المؤمنين في قومِ لوطٍ حينها، وأنّ الكثرةَ كانت على الباطل؛ فلا يدلّ قلّةُ أهلِ الحقِّ على بطلانه؛ فلا يهمّنك أنت قلّةُ أهلِ الحقِّ وكثرةُ أهلِ الباطل؛ فالعبرةُ بالحقِّ والإيمانِ لا بالكثرة؛ وقليلٌ من عبادي الشكور؛ وما آمن معه إلا قليل؛ وإن تُطِعْ أكثرَ من في الأرضِ يُضلّوك عن سبيلِ الله؛ فكن مع الحقِّ ولو قلَّ أهله، ولا تغترّ بكثرةِ أهلِ الباطل؛ فبدأ الإسلامُ غريبًا وسيعود غريبًا فطوبى للغرباء؛ فمن ثبت مع الحقِّ ولو قلَّ أهله نجا، ومن اتّبع الكثرةَ على الباطلِ هلك؛ فاجعل الثباتَ مع الحقِّ ولو قلَّ أهله دأبك."}},{"n":37,"reflection":{"text":"«وتركنا فيها آية للذين يخافون العذاب الأليم»، وتركنا في قريةِ قومِ لوطٍ علامةً وعبرةً للذين يخافون العذابَ الأليم؛ ففي هذا بيانُ أنّ الآياتِ عبرةٌ للخائفين؛ فاعتبر بآياتِ الله وعبره، وكن ممّن يخاف العذابَ فيتّعظ، فالخوفُ من العذابِ يحمل على الاعتبار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآياتِ الله، والخوفُ من العذابِ الحاملُ على الاتّعاظ."},"action":{"text":"تأمّل أنّ الآياتِ عبرةٌ للخائفين: وتركنا في قريةِ قومِ لوطٍ المدمّرةِ آيةً وعلامةً وعبرةً باقية، للذين يخافون العذابَ الأليم فيعتبرون بها ويتّعظون «وتركنا فيها آية للذين يخافون العذاب الأليم»؛ ففي هذا بيانُ أنّ الله ترك في ديارِ قومِ لوطٍ آيةً وعبرة، لكن ينتفع بها من يخاف العذاب؛ فالمنتفعُ بالعبرِ أهلُ الخوفِ من الله؛ فاعتبر أنت بآياتِ الله وعبره في المكذّبين؛ وإنكم لتمرّون عليهم مصبحين وبالليلِ أفلا تعقلون؛ وكن ممّن يخاف العذابَ فيتّعظ ويعتبر؛ إنما يخشى الله من عباده العلماء؛ سيذّكّر من يخشى؛ فالخوفُ من عذابِ الله يحمل على الاعتبارِ والاتّعاظِ والعمل؛ فمن خاف العذابَ اعتبر بالآياتِ واتّعظ، ومن أمن غفل؛ فاجعل الاعتبارَ بآياتِ الله والخوفَ من عذابه دأبك."},"qadiyya":{"title":"قضيّةُ الضيافة: سنّةٌ من ملّة إبراهيم استُخرجت من طريقة تقديم الطعام","question":"في سورة الذاريات قصّةُ ضيوف إبراهيمَ عليه السلام، وهي قصّةٌ قصيرةٌ في ظاهرها: جاءه ضيوفٌ فسلّموا، فذهب فجاءهم بعجلٍ سمين.\nوقد استخرج منها الإمامُ السعديُّ **خمسَ عشرةَ فائدةً**، أكثرُها في أدب الضيافة: كيف يُستقبل الضيف، ومن أين يُؤتى بالطعام، وكيف يُقدَّم، وبأيِّ لفظٍ يُعرض عليه.\nفالقضيّة: ما هذه الآداب؟ ومن أين استُخرجت؟ ثمّ: لماذا يُعنى القرآنُ بتفصيلٍ كهذا **في سياق سورةٍ موضوعُها الوعدُ والوعيد**؟","background":"ولا تُفهم **دقّةُ الاستخراج** حتى نقرأ الآياتِ بألفاظها من الصفر:\n﴿هل أتاك حديثُ ضيف إبراهيم المكرَمين؟ إذ دخلوا عليه فقالوا سلامًا قال سلامٌ قومٌ منكرون. فراغ إلى أهله فجاء بعجلٍ سمين. فقرّبه إليهم قال ألا تأكلون؟﴾\n**فكلُّ لفظٍ ها هنا مقصود**: «المكرَمين»، و«سلامًا» ثمّ «سلامٌ»، و«راغ» (أي: ذهب في خفية)، و«جاء» (ولم يقل: أمر)، و«قرّبه إليهم» (ولم يقل: دعاهم إليه)، و«ألا تأكلون» (عرضٌ لا أمر).\nومن هذه الألفاظ استُخرجت الآداب.","what_happened":"افتتح السعديُّ فصلَه بقوله: «فصلٌ في ذكر بعض ما تضمّنته هذه القصّة من الحكم والأحكام».\nفأوّلُ ما ذكر أنّ **في القصص حكمةً**: «منها: أنّ من الحكمة، قصُّ الله على عباده نبأَ الأخيار والفجّار، ليعتبروا بحالهم وأين وصلت بهم الأحوال».\nثمّ فضلُ إبراهيم، حيث ابتدأ اللهُ قصّتَه «بما يدلّ على الاهتمام بشأنها».\nثمّ جاء بابُ الضيافة:\n«ومنها: مشروعيّةُ الضيافة، وأنّها من سنن إبراهيمَ الخليل، الذي أمر اللهُ هذا النبيَّ وأمّتَه أن يتّبعوا ملّتَه»، ونبّه إلى أنّ الله ساقها «على وجه المدح له والثناء».\nثمّ في كيفيّة الإكرام: «ومنها: أنّ الضيف يُكرم بأنواع الإكرام، بالقول والفعل»؛ واستدلّ بأنّ الله وصف أضيافَه بأنّهم «مكرَمون»، أي أكرمهم إبراهيم، ووصف ما صنع بهم «قولًا وفعلًا».\nثمّ في هيئة بيته: «ومنها: أنّ إبراهيمَ عليه السلام قد كان بيتُه مأوًى للطارقين والأضياف»، واستدلّ بأنّهم «دخلوا عليه من غير استئذان».\nثمّ في أدب السلام: «وإنّما سلكوا طريقَ الأدب، في الابتداء السلام، فردّ عليهم إبراهيمُ سلامًا أكملَ من سلامهم وأتمّ».\nفوقف عند فرق اللفظين: قالوا ﴿سلامًا﴾ وقال ﴿سلامٌ﴾؛ والثاني جملةٌ اسميّةٌ **تدلّ على الثبوت والدوام**، والأوّل فعليّةٌ. فردَّ **بأتمَّ ممّا حُيِّي به**.","the_verdict":"فالحاصلُ أنّ الآداب لم تُؤخذ من عمومياتٍ، **بل من ألفاظٍ بأعيانها**.\nوهذا هو الدرسُ في الصنعة قبل أن يكون في الضيافة: **أنّ اللفظ في القرآن يحمل حكمًا**، وأنّ اختيار كلمةٍ دون أختها ليس زخرفًا.\n⭐ وأمّا ما في القصّة من الآداب فيُستخرج من ترتيبها، وهو ترتيبٌ يستحقّ أن يُتأمّل:\nقالوا: ﴿سلامًا﴾. فردّ: ﴿سلامٌ﴾: أتمَّ ممّا حُيّي به، وهو أصلُ قوله تعالى ﴿وإذا حُيّيتم بتحيّةٍ فحيّوا بأحسنَ منها﴾.\nثمّ ﴿فراغ إلى أهله﴾، و«راغ» تدلّ على الذهاب في خفية. فلم يُعلن لضيوفه أنّه ذاهبٌ ليُحضر الطعام، ولم يستأذنهم، لئلّا يمنعوه أو يتكلّفوا الاعتذار.\nثمّ ﴿فجاء بعجلٍ سمين﴾، جاء به هو، ولم يأمر خادمًا. و«سمين» أي: من خيار ما عنده لا من فضله.\nثمّ ﴿فقرّبه إليهم﴾، قرّبه إليهم في مجلسهم ولم يدعُهم إلى مكان الطعام.\nثمّ ﴿ألا تأكلون﴾، عرضٌ بلطف لا أمرٌ ولا إلحاح.\nفهذه **خمسُ خطواتٍ في خمس كلمات**.\nوأمّا قولُ السعديّ إنّ الضيافةَ «من سنن إبراهيم الخليل، الذي أمر اللهُ هذا النبيَّ وأمّتَه أن يتّبعوا ملّتَه» فيرفع الضيافةَ **من بابِ الكرم إلى بابِ الاتّباع**. فليست عادةً عربيّةً حسنة؛ إنّها ملّةُ إبراهيمَ التي أُمرنا باتّباعها بنصّ القرآن.\nوأمّا كونُ بيته مأوًى للطارقين حتى دخلوا بلا استئذان، ففيه وصفٌ لحالٍ لا لفعلٍ واحد: أنّ البيت عُرف بذلك حتى صار الداخلُ إليه لا يستأذن. وبين الرجل يُكرم ضيفَه إذا جاءه، والرجل يُعرف بيتُه بالضيافة، **فرقٌ كالفرق بين العمل والصفة**.","for_you":"فأمّا الذي تخرج به فأربعة، وكلُّها تُعمل في أوّل ضيفٍ يطرق بابَك:\nالأوّل: **ردَّ التحيّةَ بأحسنَ منها**. فقد ردّ إبراهيمُ بأتمَّ ممّا حُيّي به، ولم يكتفِ بالمثل. وهذا يجري في كلِّ تحيّةٍ ورسالةٍ وسلامٍ في يومك؛ ومن ردّ بالمثل فقد أدّى، ومن ردّ بأحسن فقد اتّبع.\nوالثاني: **أعِدَّ الضيافةَ بلا استئذانٍ ولا إعلان**. فقد ذهب إبراهيمُ في خفية. والذي يقول لضيفه: هل أُحضر لك طعامًا؟ يُحرجه ويضطرّه إلى الاعتذار. والسنّةُ أن يُقدَّم لا أن يُعرض على من يستحيي.\nوالثالث: **قدّمْ من خيار ما عندك**. ﴿بعجلٍ سمين﴾، لا بما فضل. والذي يُطعم ضيفَه ممّا لا يشتهيه هو قد أدّى صورةَ الضيافة وفاته مقصودُها.\nوالرابع: **اجعل الطعامَ يذهب إليه لا هو إليه**. ﴿فقرّبه إليهم﴾. وهذا لطفٌ في المعاملة يشعر به الضيفُ ولا يستطيع أن يسمّيه.\nوأمّا الخامسةُ فهي في نفسك لا في بيتك: **أن تسعى ليُعرف بيتُك بهذا، لا أن تُحسن حين يقع**. فبيتُ إبراهيمَ كان مأوًى للطارقين حتى دخلوا بلا استئذان؛ وتلك صفةٌ لا يبلغها من يُكرم إذا جاءه ضيف، إنّما يبلغها من ينتظر الضيف.","grade":"ma'thur","source":"فصلُ الفوائد في تفسير السعديّ (٥١:٣٧): افتتاحُه «فصل في ذكر بعض ما تضمنته هذه القصة من الحكم والأحكام»، وقولُه «منها: أن من الحكمة، قص الله على عباده نبأ الأخيار والفجار، ليعتبروا بحالهم وأين وصلت بهم الأحوال»، و«ومنها: مشروعية الضيافة، وأنها من سنن إبراهيم الخليل، الذي أمر الله هذا النبي وأمته، أن يتبعوا ملته»، و«ومنها: أن الضيف يكرم بأنواع الإكرام، بالقول، والفعل»، و«ومنها: أن إبراهيم عليه السلام، قد كان بيته، مأوى للطارقين والأضياف، لأنهم دخلوا عليه من غير استئذان»، و«وإنما سلكوا طريق الأدب، في الابتداء السلام فرد عليهم إبراهيم سلاما، أكمل من سلامهم وأتم»: كلُّها بنصّها.","honesty":"وممّا يجب أن يُقال:\nالخطواتُ الخمسُ التي عدَدناها في الخلاصة (ردُّ السلام، والذهابُ في خفية، والمجيءُ به بنفسه، والتقريبُ إليهم، والعرضُ بلطف) مأخوذةٌ من ألفاظ الآيات نفسِها، **وليست كلُّها منصوصةً في فصل السعديّ**؛ فالذي نصّ عليه منها ردُّ السلام بأتمَّ منه، وإكرامُ الضيف بالقول والفعل، وكونُ بيته مأوًى. وأمّا تفصيلُ «راغ» و«جاء» و«قرّبه» و«ألا تأكلون» **فاستخراجٌ منّا من لفظ الآية**، ومعانيها ظاهرة، ومن رأى أنّا وسّعنا فليردّه.\nوأمّا تفسيرُ «راغ» بالذهاب في خفية فمعنًى لغويٌّ مشهور، ولم ننقله بلفظه عن أحدٍ من الستّة في هذا الموضع.\nوأمّا تعليلُ الفرق بين ﴿سلامًا﴾ و﴿سلامٌ﴾ بالجملة الاسميّة والفعليّة، فوجهٌ نحويٌّ معروف، وقد نصّ السعديُّ على أنّ ردّه «أكمل وأتمّ» ولم يذكر هذا التعليل بعينه ها هنا.\nولم نتعرّض لأحكام الضيافة الفقهيّة ومقاديرها، ومظانُّها كتبُ الأحكام."}}]},{"title":"آياتُ موسى وعادٍ وثمودَ وقومِ نوح","range":[38,46],"theme":"إرسالُ موسى إلى فرعونَ بسلطانٍ فتولّى ورماه بالسحرِ فأُغرِق، وإرسالُ الريحِ العقيمِ على عادٍ فجعلتهم كالرميم، وإمهالُ ثمودَ فعتوا فأخذتهم الصاعقةُ فما استطاعوا قيامًا، وإهلاكُ قومِ نوحٍ لفسقهم","verses":[{"n":38,"reflection":{"text":"«وفي موسى إذ أرسلناه إلى فرعون بسلطان مبين»، وفي قصةِ موسى آيةٌ، إذ أرسلناه إلى فرعونَ بحجّةٍ واضحة؛ ففي هذا التذكيرُ بقصةِ موسى وفرعون؛ فاعتبر بقصةِ موسى وإرسالِه بالحجّة، فالله يؤيّد رسله بالبراهين، فاتّبع الحقَّ ببرهانه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بقصةِ موسى، واتّباعُ الحقِّ ببرهانه."},"action":{"text":"تأمّل التذكيرَ بقصةِ موسى: وفي قصةِ موسى عليه السلام آيةٌ وعبرةٌ أخرى، إذ أرسلناه إلى فرعونَ الطاغيةِ بسلطانٍ مبينٍ، أي بحجّةٍ واضحةٍ وبراهينَ ومعجزاتٍ ظاهرة «وفي موسى إذ أرسلناه إلى فرعون بسلطان مبين»؛ ففي هذا التذكيرُ بقصةِ موسى وإرسالِه إلى فرعونَ بالحجّةِ الواضحة؛ فأيّده الله بالبراهينِ والمعجزات؛ فاعتبر أنت بقصةِ موسى وفرعون؛ وكيف أيّد الله موسى بالحجّةِ المبينة؛ ولقد آتينا موسى تسعَ آياتٍ بيّنات؛ فالله يؤيّد رسله وأولياءه بالحججِ والبراهين؛ فاتّبع الحقَّ ببرهانه ودليله؛ ولا تردّ الحقَّ المؤيَّدَ بالبرهانِ كما ردّه فرعون؛ فمن اتّبع الحقَّ ببرهانه اهتدى، ومن ردّه كفرعونَ هلك؛ فاجعل الاعتبارَ بقصةِ موسى واتّباعَ الحقِّ ببرهانه دأبك."}},{"n":39,"reflection":{"text":"«فتولى بركنه وقال ساحر أو مجنون»: فأعرض فرعونُ معتمدًا على قوّته وجنده، وقال في موسى: ساحرٌ أو مجنون؛ ففي هذا بيانُ إعراضِ فرعونَ واغتراره بقوّته؛ فاحذر الإعراضَ عن الحقِّ والاغترارَ بالقوّة، ورميَ الحقِّ بالتهم، فالاغترارُ بالقوّةِ ورميُ الحقِّ بالباطلِ من صفاتِ الطغاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ وتركُ الاغترارِ بالقوّة، وعدمُ رميِ الحقِّ بالتهم."},"action":{"text":"تأمّل إعراضَ فرعون: فتولّى فرعونُ وأعرض عن الحقِّ الذي جاء به موسى، معتمدًا على ركنه، أي قوّته وجنده وملكه، مغترًّا بها؛ وقال في موسى ودعوته: هو ساحرٌ أو مجنون، رميًا له بالباطل «فتولى بركنه وقال ساحر أو مجنون»؛ ففي هذا بيانُ إعراضِ فرعونَ عن الحقِّ واغتراره بقوّته، ورميه موسى بالسحرِ والجنون؛ فأعرض مغترًّا بقوّته، ورمى الحقَّ بالتهم؛ فاحذر أنت الإعراضَ عن الحقِّ والاغترارَ بالقوّةِ والجاهِ والمال؛ واحذر رميَ الحقِّ وأهله بالتهمِ الباطلة؛ فرميُ الرسلِ بالسحرِ والجنونِ من صفاتِ الطغاة؛ كذلك ما أتى الذين من قبلهم من رسولٍ إلا قالوا ساحرٌ أو مجنون؛ فالاغترارُ بالقوّةِ ورميُ الحقِّ بالباطلِ سببُ الهلاك؛ فمن قبل الحقَّ وتواضع نجا، ومن أعرض واغترّ بقوّته هلك؛ فاجعل قبولَ الحقِّ وتركَ الاغترارِ بالقوّةِ دأبك."}},{"n":40,"reflection":{"text":"«فأخذناه وجنوده فنبذناهم في اليم وهو مليم»: فأخذنا فرعونَ وجنوده فألقيناهم في البحرِ (أغرقناهم) وهو ملومٌ آتٍ بما يُلام عليه؛ ففي هذا بيانُ عاقبةِ فرعونَ وجنوده؛ فاعتبر بإغراقِ فرعونَ وجنوده، فالطغيانُ والإعراضُ عن الحقِّ سببُ الهلاك، فاحذر عاقبةَ الطغاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ الطغاة، والحذرُ من الطغيانِ والإعراض."},"action":{"text":"تأمّل عاقبةَ فرعون: فأخذنا فرعونَ وجنوده أخذَ عزيزٍ مقتدر، فنبذناهم، أي ألقيناهم وطرحناهم، في اليمِّ (البحر) فأغرقناهم جميعًا؛ وهو مليمٌ، أي آتٍ بما يُلام عليه من الكفرِ والطغيانِ والعناد «فأخذناه وجنوده فنبذناهم في اليم وهو مليم»؛ ففي هذا بيانُ عاقبةِ فرعونَ وجنوده: الإغراقُ في البحرِ جزاءَ طغيانهم؛ فأهلكهم الله بإعراضهم واغترارهم؛ فاعتبر أنت بإغراقِ فرعونَ وجنوده رغمَ قوّتهم؛ فأخذناه وجنوده فنبذناهم في اليم فانظر كيف كان عاقبةُ الظالمين؛ فأغرقناهم أجمعين؛ فالطغيانُ والإعراضُ عن الحقِّ والاغترارُ بالقوّةِ سببُ الهلاك؛ فاحذر عاقبةَ الطغاةِ المعرضين عن الحق؛ فمن اتّعظ بعاقبةِ الطغاةِ نجا، ومن سلك سبيلهم هلك؛ فاجعل الاعتبارَ بعاقبةِ الطغاةِ والحذرَ من الطغيانِ دأبك."}},{"n":41,"reflection":{"text":"«وفي عاد إذ أرسلنا عليهم الريح العقيم»، وفي قصةِ عادٍ آيةٌ، إذ أرسلنا عليهم الريحَ العقيمَ التي لا خيرَ فيها؛ ففي هذا التذكيرُ بإهلاكِ عادٍ بالريح؛ فاعتبر بإهلاكِ عادٍ بالريح، فالتكذيبُ والاستكبارُ سببُ الهلاك، فاحذر أن يصيبك ما أصابهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإهلاكِ عاد، والحذرُ من التكذيبِ والاستكبار."},"action":{"text":"تأمّل إهلاكَ عادٍ بالريح: وفي قصةِ عادٍ، قومِ هودٍ، آيةٌ وعبرةٌ أخرى، إذ أرسلنا عليهم الريحَ العقيمَ، أي التي لا خيرَ فيها ولا بركة، لا تحمل مطرًا ولا تُلقِح شجرًا، بل تدمّر وتهلك «وفي عاد إذ أرسلنا عليهم الريح العقيم»؛ ففي هذا التذكيرُ بإهلاكِ عادٍ بالريحِ العقيمِ المدمّرة؛ فأهلكهم الله بالريحِ جزاءَ تكذيبهم واستكبارهم؛ فاعتبر أنت بإهلاكِ عادٍ بالريحِ رغمَ قوّتهم؛ وأمّا عادٌ فأُهلِكوا بريحٍ صرصرٍ عاتية، سخّرها عليهم سبعَ ليالٍ وثمانيةَ أيامٍ حسومًا؛ فأمّا عادٌ فاستكبروا في الأرضِ بغيرِ الحق؛ فالتكذيبُ والاستكبارُ سببُ الهلاك؛ فاحذر أن يصيبك ما أصاب عادًا من التكذيبِ والاستكبار؛ فمن اتّعظ بإهلاكِ عادٍ نجا، ومن سلك سبيلهم هلك؛ فاجعل الاعتبارَ بإهلاكِ عادٍ والحذرَ من التكذيبِ والاستكبارِ دأبك."}},{"n":42,"reflection":{"text":"«ما تذر من شيء أتت عليه إلا جعلته كالرميم»: لا تترك تلك الريحُ شيئًا أتت عليه إلا جعلته كالشيءِ الباليِ المتفتّت؛ ففي هذا بيانُ شدّةِ عذابِ عاد؛ فاعتبر بشدّةِ عذابِ الله للطغاة، فقدرةُ الله على العذابِ عظيمة، فاتّق الله واحذر عذابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بشدّةِ عذابِ الله، والحذرُ من عذابه."},"action":{"text":"تأمّل شدّةَ عذابِ عاد: تلك الريحُ العقيمُ ما تذر وما تترك من شيءٍ أتت عليه من الأنفسِ والأموالِ والديار، إلا جعلته كالرميمِ، أي كالشيءِ الباليِ المتفتّتِ المتهشّم، كالتبنِ والعظمِ البالي «ما تذر من شيء أتت عليه إلا جعلته كالرميم»؛ ففي هذا بيانُ شدّةِ الريحِ التي أهلكت عادًا، وأنها لم تترك شيئًا إلا دمّرته؛ فدمّرت كلَّ ما مرّت به؛ فاعتبر أنت بشدّةِ عذابِ الله للطغاةِ المكذّبين؛ فترى القومَ فيها صرعى كأنهم أعجازُ نخلٍ خاوية؛ تدمّر كلَّ شيءٍ بأمرِ ربّها؛ فقدرةُ الله على العذابِ عظيمةٌ لا تُقاوَم؛ إنّ بطشَ ربّك لشديد؛ فاتّق الله واحذر عذابه وبطشه؛ فمن اتّقى الله وحذر عذابه نجا، ومن أمن مكره هلك؛ فاجعل الاعتبارَ بشدّةِ عذابِ الله والحذرَ منه دأبك."}},{"n":43,"reflection":{"text":"«وفي ثمود إذ قيل لهم تمتعوا حتى حين»، وفي قصةِ ثمودَ آيةٌ، إذ قيل لهم: تمتّعوا في دياركم إلى حينٍ (ثلاثةِ أيامٍ) ثم يأتيكم العذاب؛ ففي هذا التذكيرُ بإمهالِ ثمودَ قبل العذاب؛ فلا تغترّ بالإمهال، فالإمهالُ ليس إهمالًا، فبادر بالتوبةِ قبل انقضاءِ الأجل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالإمهال، والمبادرةُ بالتوبةِ قبل الأجل."},"action":{"text":"تأمّل إمهالَ ثمود: وفي قصةِ ثمودَ، قومِ صالحٍ، آيةٌ وعبرة، إذ قيل لهم بعد عقرِ الناقة: تمتّعوا في دياركم وحياتكم حتى حينٍ، أي ثلاثةَ أيامٍ فقط، ثم يأتيكم العذاب؛ فأُمهِلوا قليلًا «وفي ثمود إذ قيل لهم تمتعوا حتى حين»؛ ففي هذا التذكيرُ بإمهالِ ثمودَ ثلاثةَ أيامٍ قبل العذاب؛ فأُمهِلوا مدّةً يسيرةً ثم أُهلِكوا؛ فلا تغترّ أنت بالإمهالِ والتأخير؛ فالإمهالُ ليس إهمالًا، بل استدراج؛ ولا يحسبنّ الذين كفروا أنما نملي لهم خيرٌ لأنفسهم، إنما نملي لهم ليزدادوا إثمًا؛ فمهّل الكافرين أمهلهم رويدًا؛ فبادر أنت بالتوبةِ والعملِ الصالحِ قبل انقضاءِ الأجلِ ونزولِ العذاب؛ فتمتّعوا في داركم ثلاثةَ أيامٍ ذلك وعدٌ غيرُ مكذوب؛ فمن بادر بالتوبةِ قبل الأجلِ نجا، ومن اغترّ بالإمهالِ حتى فاجأه العذابُ هلك؛ فاجعل عدمَ الاغترارِ بالإمهالِ والمبادرةَ بالتوبةِ دأبك."}},{"n":44,"reflection":{"text":"«فعتوا عن أمر ربهم فأخذتهم الصاعقة وهم ينظرون»: فتكبّروا وتجاوزوا أمرَ ربّهم، فأخذتهم الصاعقةُ (العذاب) وهم ينظرون إليها؛ ففي هذا بيانُ عاقبةِ العتوِّ عن أمرِ الله؛ فاحذر العتوَّ والتكبّرَ عن أمرِ الله، فامتثل أمره ولا تعتُ عنه، فالعتوُّ عن أمرِ الله سببُ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"امتثالُ أمرِ الله، والحذرُ من العتوِّ والتكبّرِ عنه."},"action":{"text":"تأمّل عاقبةَ العتوّ: فعتا ثمودُ وتكبّروا وتجاوزوا أمرَ ربّهم، فلم يمتثلوا ولم يتوبوا في مدّةِ الإمهال، بل استمرّوا في كفرهم؛ فأخذتهم الصاعقةُ، وهي العذابُ المهلك، الصيحةُ أو الرجفة، وهم ينظرون إليها معاينين لها «فعتوا عن أمر ربهم فأخذتهم الصاعقة وهم ينظرون»؛ ففي هذا بيانُ أنّ ثمودَ عتوا عن أمرِ ربّهم فأخذهم العذاب؛ فتجاوزوا أمرَ الله وتكبّروا فأُهلِكوا؛ فاحذر أنت العتوَّ والتكبّرَ والتجاوزَ لأمرِ الله؛ فامتثل أمرَ الله ونهيه، ولا تعتُ عنه ولا تتكبّر؛ وعتت عن أمرِ ربّها ورسله فحاسبناها حسابًا شديدًا؛ فأمّا ثمودُ فأُهلِكوا بالطاغية؛ فالعتوُّ والتكبّرُ عن أمرِ الله سببُ العذابِ والهلاك؛ فمن امتثل أمرَ الله نجا، ومن عتا عنه هلك؛ فاجعل امتثالَ أمرِ الله والحذرَ من العتوِّ عنه دأبك."}},{"n":45,"reflection":{"text":"«فما استطاعوا من قيام وما كانوا منتصرين»: فما استطاعوا نهوضًا من مصارعهم، وما كانوا منتصرين ممتنعين من العذاب؛ ففي هذا بيانُ عجزهم أمام عذابِ الله؛ فاعلم أنّ لا أحدَ يمتنع من عذابِ الله، فلا تأمن عذابه، فمن أخذه الله لم ينتصر ولم يقم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الأمنِ من عذابِ الله، وإدراكُ العجزِ أمامه."},"action":{"text":"تأمّل عجزهم أمام العذاب: فما استطاع ثمودُ لمّا أخذتهم الصاعقةُ من قيامٍ ونهوضٍ من مصارعهم، بل صُرِعوا هامدين؛ وما كانوا منتصرين ممتنعين من عذابِ الله، ولا منتقمين لأنفسهم «فما استطاعوا من قيام وما كانوا منتصرين»؛ ففي هذا بيانُ عجزِ ثمودَ التامِّ أمام عذابِ الله، فلا قيامَ ولا انتصار؛ فأخذهم العذابُ فلم يقدروا على دفعه ولا الامتناعِ منه؛ فاعلم أنت أنه لا أحدَ يمتنع من عذابِ الله أو ينتصر منه؛ فما كان له من فئةٍ ينصرونه من دونِ الله وما كان منتصرًا؛ فما له من قوّةٍ ولا ناصر؛ فلا تأمن أنت عذابَ الله ومكره؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فمن أخذه الله بعذابه لم ينتصر ولم يقم؛ فمن خاف عذابَ الله واستعدّ نجا، ومن أمنه هلك؛ فاجعل عدمَ الأمنِ من عذابِ الله وإدراكَ العجزِ أمامه دأبك."}},{"n":46,"reflection":{"text":"«وقوم نوح من قبل إنهم كانوا قوما فاسقين»، وأهلكنا قومَ نوحٍ من قبل هؤلاء، إنهم كانوا قومًا فاسقين خارجين عن الطاعة؛ ففي هذا بيانُ عاقبةِ الفسق؛ فاحذر الفسقَ والخروجَ عن طاعةِ الله، فالفسقُ سببُ الهلاك، فالزم الطاعةَ لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الطاعة، والحذرُ من الفسقِ والخروجِ عنها."},"action":{"text":"تأمّل عاقبةَ قومِ نوح: وأهلكنا قومَ نوحٍ من قبلِ هؤلاء المذكورين بالطوفان؛ إنهم كانوا قومًا فاسقين خارجين عن طاعةِ الله، متمرّدين على رسوله «وقوم نوح من قبل إنهم كانوا قوما فاسقين»؛ ففي هذا بيانُ إهلاكِ قومِ نوحٍ بسببِ فسقهم وخروجهم عن الطاعة؛ فأهلكهم الله بالغرقِ جزاءَ فسقهم وتكذيبهم؛ فاحذر أنت الفسقَ والخروجَ عن طاعةِ الله؛ فالفسقُ سببُ الهلاكِ والعذاب؛ فكلًّا أخذنا بذنبه؛ فأخذهم الطوفانُ وهم ظالمون؛ فالزم أنت طاعةَ الله ورسوله، ولا تخرج عنها بالفسقِ والعصيان؛ فمن لزم الطاعةَ نجا، ومن فسق وخرج عنها هلك؛ فاجعل لزومَ الطاعةِ والحذرَ من الفسقِ دأبك."}}]},{"title":"آياتُ الخلق، والأمرُ بالفرارِ إلى الله والتوحيد","range":[47,51],"theme":"بناءُ السماءِ بأيدٍ وفرشُ الأرضِ وخلقُ كلِّ شيءٍ زوجين للتذكّر، والأمرُ بالفرارِ إلى الله وأنه نذيرٌ مبين، والنهيُ عن جعلِ إلهٍ آخرَ مع الله","verses":[{"n":47,"reflection":{"text":"«والسماء بنيناها بأيد وإنا لموسعون»، والسماءَ بنيناها بقوّةٍ وقدرة، وإنا لقادرون على توسيعها وموسّعون في الرزقِ والخلق؛ ففي هذا بيانُ عظمةِ خلقِ السماءِ وقدرةِ الله؛ فتأمّل عظمةَ بناءِ السماءِ بقدرةِ الله، فمن بناها بقوّةٍ قادرٌ على كلِّ شيء، فعظّم قدرةَ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ قدرةِ الله في خلقِ السماء، والاستدلالُ بها."},"action":{"text":"تأمّل عظمةَ خلقِ السماء: والسماءَ بنيناها بأيدٍ، أي بقوّةٍ وقدرةٍ عظيمة؛ وإنا لموسعون، أي قادرون على توسيعها وسعتها، أو موسّعون على خلقنا في الرزقِ والفضل «والسماء بنيناها بأيد وإنا لموسعون»؛ ففي هذا بيانُ عظمةِ بناءِ السماءِ بقدرةِ الله وقوّته، وسعةِ قدرته وفضله؛ فبناها بقوّةٍ وأحكمها؛ فتأمّل أنت عظمةَ بناءِ السماءِ المحكمِ بقدرةِ الله؛ أأنتم أشدُّ خلقًا أم السماءُ بناها، رفع سمكها فسوّاها؛ وبنينا فوقكم سبعًا شدادًا؛ فمن بنى السماءَ بقوّةٍ وقدرةٍ قادرٌ على كلِّ شيء، وعلى البعثِ والإعادة؛ فعظّم أنت قدرةَ الله في خلقِ السماءِ العظيم؛ فمن تأمّل عظمةَ خلقِ السماءِ عظّم الخالقَ وأيقن بقدرته؛ فاجعل تعظيمَ قدرةِ الله والاستدلالَ بخلقِ السماءِ دأبك."}},{"n":48,"reflection":{"text":"«والأرض فرشناها فنعم الماهدون»، والأرضَ بسطناها ومهّدناها لتستقرّوا عليها، فنِعم الماهدون نحن؛ ففي هذا بيانُ نعمةِ تمهيدِ الأرض؛ فاشكر الله على تمهيدِ الأرضِ لك، فبها استقرارك وحياتك، فنعمةُ الأرضِ الممهّدةِ تستوجب الشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ تمهيدِ الأرض، وإدراكُ فضلِ الله فيها."},"action":{"text":"تأمّل نعمةَ تمهيدِ الأرض: والأرضَ فرشناها وبسطناها ومهّدناها ووطّأناها لكم لتستقرّوا وتعيشوا عليها؛ فنِعم الماهدون نحن، الذين مهّدناها لكم وهيّأناها لمنافعكم «والأرض فرشناها فنعم الماهدون»؛ ففي هذا بيانُ نعمةِ الله بتمهيدِ الأرضِ وفرشها للناس؛ فمهّدها الله وذلّلها لتكون فراشًا ومستقرًّا؛ فاشكر أنت الله على نعمةِ تمهيدِ الأرضِ وفرشها لك؛ فبها استقرارك وسكناك وزرعك وحياتك؛ الذي جعل لكم الأرضَ فراشًا؛ ألم نجعلِ الأرضَ مهادًا؛ والأرضَ مددناها؛ هو الذي جعل لكم الأرضَ ذلولًا فامشوا في مناكبها وكلوا من رزقه؛ فنعمةُ الأرضِ الممهّدةِ من أعظمِ نعمِ الله؛ فمن شكر نعمةَ الأرضِ زاده الله، ومن كفرها استحقّ سلبها؛ فاجعل شكرَ نعمةِ تمهيدِ الأرضِ واستعمالها في الطاعةِ دأبك."}},{"n":49,"reflection":{"text":"«ومن كل شيء خلقنا زوجين لعلكم تذكرون»، ومن كلِّ شيءٍ خلقنا زوجين (ذكرًا وأنثى، ونوعين متقابلين) لعلّكم تتذكّرون قدرةَ الله ووحدانيته؛ ففي هذا الاستدلالُ بالأزواجِ على الخالق؛ فتذكّر بخلقِ الأزواجِ وحدانيةَ الخالق، فالخالقُ للأزواجِ واحدٌ لا زوجَ له، فوحّد الله المتفرّد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكّرُ بخلقِ الأزواجِ لوحدانيةِ الخالق، وتوحيدُ المتفرّد."},"action":{"text":"تأمّل الاستدلالَ بالأزواج: ومن كلِّ شيءٍ خلقنا زوجين اثنين متقابلين: ذكرًا وأنثى، وليلًا ونهارًا، وسماءً وأرضًا، وبرًّا وبحرًا، وشمسًا وقمرًا، وسعادةً وشقاء؛ لعلّكم تتذكّرون بذلك قدرةَ الله ووحدانيته، وأنّ الخالقَ للأزواجِ واحدٌ لا زوجَ له ولا نظير «ومن كل شيء خلقنا زوجين لعلكم تذكرون»؛ ففي هذا الاستدلالُ بخلقِ الأشياءِ أزواجًا على قدرةِ الله ووحدانيته؛ فكلُّ المخلوقاتِ أزواج، والخالقُ فردٌ لا زوجَ له؛ فتذكّر أنت بخلقِ الأزواجِ وحدانيةَ الخالقِ وتفرّده؛ سبحان الذي خلق الأزواجَ كلَّها ممّا تنبت الأرضُ ومن أنفسهم وممّا لا يعلمون؛ وأنه خلق الزوجين الذكرَ والأنثى؛ فالخالقُ للأزواجِ المتقابلةِ واحدٌ لا شريكَ له ولا نظير؛ ليس كمثله شيء؛ فوحّد أنت الله المتفرّدَ الذي لا زوجَ له ولا نظير؛ فمن تذكّر بخلقِ الأزواجِ وحّد الخالق، ومن غفل أشرك؛ فاجعل التذكّرَ بخلقِ الأزواجِ وتوحيدَ الله المتفرّدِ دأبك."}},{"n":50,"reflection":{"text":"«ففروا إلى الله إني لكم منه نذير مبين»: ففرّوا إلى الله (من عذابه إلى رحمته، ومن معصيته إلى طاعته)، إني لكم منه نذيرٌ مبين؛ ففي هذا الأمرُ بالفرارِ إلى الله؛ ففرَّ إلى الله من كلِّ ما يُبعِدك عنه: من الشركِ والمعاصي والغفلة، إلى توحيده وطاعته، فالفرارُ إلى الله سبيلُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الفرارُ إلى الله من كلِّ ما يُبعِد عنه، إلى توحيده وطاعته."},"action":{"text":"تأمّل الأمرَ بالفرارِ إلى الله: ففرّوا، أيها الناس، إلى الله؛ أي اهربوا من عذابه إلى رحمته، ومن معصيته إلى طاعته، ومن الجهلِ إلى العلم، ومن الشركِ إلى التوحيد، ومن كلِّ ما يُبعِدكم عنه إلى ما يقرّبكم إليه؛ قل النبيُّ: إني لكم منه نذيرٌ مبينٌ واضحُ الإنذار «ففروا إلى الله إني لكم منه نذير مبين»؛ ففي هذا الأمرُ العظيمُ بالفرارِ إلى الله؛ وهو جِماعُ الدين: الهربُ من كلِّ مكروهٍ إلى الله، والإقبالُ عليه بالتوحيدِ والطاعةِ والتوبة؛ ففرَّ أنت إلى الله من الشركِ إلى التوحيد، ومن المعصيةِ إلى الطاعة، ومن الغفلةِ إلى الذكر، ومن البعدِ إلى القرب؛ وأنيبوا إلى ربّكم وأسلموا له؛ وتوبوا إلى الله جميعًا أيها المؤمنون؛ ففِرارُك من الله إليه؛ فالفرارُ إلى الله سبيلُ النجاةِ والسعادة؛ فمن فرَّ إلى الله نجا وسعد، ومن فرَّ منه هلك وشقي؛ فاجعل الفرارَ إلى الله من كلِّ ما يُبعِدك عنه دأبك."}},{"n":51,"reflection":{"text":"«ولا تجعلوا مع الله إلها آخر إني لكم منه نذير مبين»، ولا تجعلوا مع الله معبودًا آخر، إني لكم منه نذيرٌ مبين؛ ففي هذا الأمرُ بالتوحيدِ والنهيُ عن الشرك؛ فوحّد الله ولا تشرك به، فالتوحيدُ أصلُ الدين، والشركُ أعظمُ الذنوب، فأخلص عبادتك لله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله وإخلاصُ العبادةِ له، والنهيُ عن الشرك."},"action":{"text":"تأمّل الأمرَ بالتوحيد: ولا تجعلوا، أيها الناس، مع الله إلهًا آخرَ تعبدونه وتدعونه؛ بل وحّدوه وأخلصوا له العبادة؛ قل النبيُّ: إني لكم منه نذيرٌ مبينٌ واضحُ الإنذارِ من الشركِ وعواقبه «ولا تجعلوا مع الله إلها آخر إني لكم منه نذير مبين»؛ ففي هذا الأمرُ بالتوحيدِ والنهيُ عن الشرك، بعد الأمرِ بالفرارِ إلى الله؛ فكرّر النذارةَ تأكيدًا؛ فالفرارُ إلى الله يقتضي توحيده وتركَ الشرك؛ فوحّد أنت الله ولا تجعل معه إلهًا آخر؛ ولا تدعُ مع الله إلهًا آخر؛ فلا تجعل مع الله إلهًا آخرَ فتقعد مذمومًا مخذولًا؛ واعبدوا الله ولا تشركوا به شيئًا؛ فالتوحيدُ أصلُ الدينِ وأساسه، والشركُ أعظمُ الذنوبِ وأخطرها؛ إنّ الله لا يغفر أن يُشرَك به؛ فأخلص أنت عبادتك ودعاءك وخوفك ورجاءك لله وحده؛ فمن وحّد الله وأخلص له نجا، ومن أشرك هلك؛ فاجعل توحيدَ الله وإخلاصَ العبادةِ له وتركَ الشركِ دأبك."}}]},{"title":"تسليةُ النبيِّ، والغايةُ من الخلق، ووعيدُ الكافرين","range":[52,60],"theme":"تسليةُ النبيِّ بأنّ تكذيبَ الرسلِ ورميهم بالسحرِ والجنونِ سنّةٌ في الطاغين، وأمرُه بالتولّي عنهم فما هو بملومٍ وبالتذكيرِ فإنّ الذكرى تنفع المؤمنين، وتقريرُ أنّ الغايةَ من خلقِ الجنِّ والإنسِ عبادةُ الله وأنه غنيٌّ عنهم الرزّاقُ ذو القوّة، وختمُ السورةِ بأنّ للظالمين نصيبًا من العذابِ فلا يستعجلوه، وويلٍ للكافرين من يومهم الموعود","verses":[{"n":52,"reflection":{"text":"«كذلك ما أتى الذين من قبلهم من رسول إلا قالوا ساحر أو مجنون»: كذلك ما جاء الذين من قبلِ قومك رسولٌ إلا قالوا: ساحرٌ أو مجنون؛ ففي هذا تسليةٌ للنبيِّ بأنّ تكذيبَ الرسلِ سنّةُ المكذّبين؛ فاصبر على التكذيبِ فإنه سنّةُ المكذّبين مع الرسل، ولا يحزنك قولهم، فتكذيبُ الحقِّ قديمٌ في المعرضين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على التكذيب، وإدراكُ أنه سنّةُ المكذّبين مع الرسل."},"action":{"text":"تأمّل تسليةَ النبيّ: كذلك، كما كذّبك قومك يا محمدُ ورموك بالسحرِ والجنون، ما أتى الذين من قبلهم من الأممِ من رسولٍ يدعوهم إلى الله، إلا قالوا فيه: ساحرٌ أو مجنون؛ فهذه سنّةُ المكذّبين مع رسلهم في كلِّ زمان «كذلك ما أتى الذين من قبلهم من رسول إلا قالوا ساحر أو مجنون»؛ ففي هذا تسليةٌ للنبيِّ ﷺ بأنّ تكذيبَ قومه له، ورميهم إياه بالسحرِ والجنون، سنّةٌ قديمةٌ في المكذّبين مع رسلهم؛ فما من رسولٍ إلا كُذِّب ورُمِي بالسحرِ والجنون؛ فاصبر أنت على التكذيبِ والأذى إن أصابك في سبيلِ الحق؛ فإنه سنّةُ المكذّبين مع الرسلِ وأتباعهم؛ ولقد كُذِّبت رسلٌ من قبلك فصبروا على ما كُذِّبوا وأوذوا؛ ما يُقال لك إلا ما قد قيل للرسلِ من قبلك؛ ولا يحزنك قولهم؛ فتكذيبُ الحقِّ ورميُ أهله بالتهمِ قديمٌ في المعرضين؛ فمن صبر على التكذيبِ في سبيلِ الحقِّ نُصِر، ومن جزع خسر؛ فاجعل الصبرَ على التكذيبِ وإدراكَ أنه سنّةُ المكذّبين دأبك."}},{"n":53,"reflection":{"text":"«أتواصوا به بل هم قوم طاغون»: أأوصى بعضهم بعضًا بهذا التكذيب؟ بل هم قومٌ طاغون جمعهم الطغيان؛ ففي هذا بيانُ أنّ الطغيانَ جامعُ المكذّبين؛ فاحذر الطغيانَ الذي يجمع أهلَ الباطلِ على تكذيبِ الحقّ، فالطغيانُ أصلُ التكذيب، فاجتنبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الطغيان، وإدراكُ أنه جامعُ المكذّبين."},"action":{"text":"تأمّل أنّ الطغيانَ جامعُ المكذّبين: أتواصى الأوّلون والآخرون من المكذّبين بهذا التكذيبِ ورميِ الرسلِ بالسحرِ والجنون، حتى اتّفقت كلمتهم عليه؟ لا؛ بل هم قومٌ طاغون متجاوزون الحدَّ في الكفرِ والعناد، جمعهم الطغيانُ فتشابهت أقوالهم «أتواصوا به بل هم قوم طاغون»؛ ففي هذا بيانُ أنّ المكذّبين لم يتواصوا بالتكذيب، بل جمعهم الطغيانُ فتشابهت قلوبهم وأقوالهم؛ فالطغيانُ هو الجامعُ لهم على تكذيبِ الحق؛ فاحذر أنت الطغيانَ والتجاوزَ للحدِّ في الكفرِ والمعاصي؛ فالطغيانُ أصلُ التكذيبِ وجامعُ أهلِ الباطل؛ كذلك ما أتى الذين من قبلهم من رسولٍ... تشابهت قلوبهم؛ إنه طغى؛ اذهب إلى فرعونَ إنه طغى؛ فمن اجتنب الطغيانَ سلم من التكذيب، ومن طغى وقع فيه؛ فاجعل اجتنابَ الطغيانِ والتجاوزِ للحدِّ دأبك."}},{"n":54,"reflection":{"text":"«فتول عنهم فما أنت بملوم»: فأعرض، يا محمدُ، عن هؤلاء المعاندين، فما أنت بملومٍ (فقد بلّغت وأدّيت)؛ ففي هذا بيانُ أنّ النبيَّ أدّى ما عليه؛ فبلّغ الحقَّ ثم أعرض عن المعاندين، فلست ملومًا بعد البلاغ، فما عليك إلا البلاغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البلاغُ ثم الإعراضُ عن المعاندين، وإدراكُ أنّ الملامةَ ترتفع بالبلاغ."},"action":{"text":"تأمّل أنّ النبيَّ أدّى ما عليه: فتولَّ وأعرض، يا محمدُ، عن هؤلاء المعاندين الطاغين الذين لا يستجيبون؛ فما أنت بملومٍ ولا معاتَبٍ في ذلك، فقد بلّغتهم وأدّيت ما عليك، وقامت الحجّة «فتول عنهم فما أنت بملوم»؛ ففي هذا بيانُ أنّ النبيَّ ﷺ أدّى ما عليه من البلاغ، فلا لومَ عليه في إعراضِ المعاندين؛ فأمره بالإعراضِ عنهم بعد البلاغ؛ فبلّغ أنت الحقَّ لمن حولك، ثم أعرض عن المعاندين المصرّين؛ فلست ملومًا بعد أداءِ ما عليك من البلاغ؛ فإن تولّوا فإنما عليك البلاغ؛ ما على الرسولِ إلا البلاغ؛ فما عليك إلا البلاغُ والبيان، لا الهدايةُ والإجبار؛ لست عليهم بمصيطر؛ فمن بلّغ ثم أعرض عن المعاندِ أدّى ما عليه، ومن حمّل نفسه هدايتهم أتعبها؛ فاجعل البلاغَ ثم الإعراضَ عن المعاندين دأبك."}},{"n":55,"reflection":{"text":"«وذكر فإن الذكرى تنفع المؤمنين»، وذكّر، يا محمدُ، بالقرآنِ والمواعظ، فإنّ الذكرى تنفع المؤمنين؛ ففي هذا بيانُ أنّ التذكيرَ ينفع المؤمنين؛ فذكّر ولا تملّ، فالذكرى تنفع أهلَ الإيمان، فاجعل التذكيرَ والتذكّرَ دأبك، وكن ممّن ينتفع بالذكرى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكيرُ والتذكّرُ، والانتفاعُ بالذكرى لأهلِ الإيمان."},"action":{"text":"تأمّل أنّ الذكرى تنفع المؤمنين: وذكّر، يا محمدُ، بالقرآنِ والمواعظِ والعبرِ ولا تملّ؛ فإنّ الذكرى والتذكيرَ تنفع المؤمنين، فتزيدهم إيمانًا وبصيرةً وعملًا، وإن لم ينتفع بها المعاندون «وذكر فإن الذكرى تنفع المؤمنين»؛ ففي هذا بيانُ أنّ التذكيرَ والموعظةَ تنفع المؤمنين، فلا يُترَك التذكيرُ لإعراضِ المعاندين؛ فالمؤمنُ ينتفع بالذكرى ويزداد بها؛ فذكّر أنت ولا تملّ من التذكيرِ والوعظِ والدعوة؛ وإذا تُليت عليهم آياته زادتهم إيمانًا؛ وتواصوا بالحقِّ وتواصوا بالصبر؛ فذكّر إن نفعتِ الذكرى، سيذّكّر من يخشى؛ وكن أنت ممّن ينتفع بالذكرى، فتذكّر عند سماعِ المواعظِ والقرآن؛ فالذكرى تنفع أهلَ الإيمانِ والخشية؛ فمن ذكّر وتذكّر انتفع، ومن ترك التذكيرَ أو أعرض عن الذكرى خسر؛ فاجعل التذكيرَ للناسِ والتذكّرَ في نفسك دأبك."}},{"n":56,"reflection":{"text":"«وما خلقت الجن والإنس إلا ليعبدون»، وما خلقت الجنَّ والإنسَ إلا ليعبدوني وحدي؛ ففي هذا بيانُ الغايةِ العظمى من الخلق: العبادة؛ فاعلم أنك خُلِقت للعبادة، فحقّق الغايةَ من خلقك بعبادةِ الله وحده، فالعبادةُ هي غايةُ وجودك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الغايةِ من الخلق بعبادةِ الله وحده."},"action":{"text":"تأمّل الغايةَ من الخلق: وما خلقت الجنَّ والإنسَ إلا ليعبدوني وحدي، ويوحّدوني، ويطيعوني؛ فالعبادةُ هي الغايةُ العظمى من خلقهم، لا حاجةً منّي إليهم «وما خلقت الجن والإنس إلا ليعبدون»؛ ففي هذا بيانُ أنّ الغايةَ من خلقِ الجنِّ والإنسِ عبادةُ الله وحده؛ فما خُلِقوا للأكلِ والشربِ واللهو، بل للعبادة؛ فاعلم أنت أنك خُلِقت لعبادةِ الله وحده؛ فحقّق الغايةَ من خلقك بعبادةِ الله: توحيدًا وطاعةً وذلًّا ومحبّةً وخوفًا ورجاءً؛ يا أيها الناس اعبدوا ربّكم الذي خلقكم؛ فاعبد الله كأنك تراه؛ والعبادةُ تشمل كلَّ ما يحبّه الله ويرضاه من الأقوالِ والأعمالِ الظاهرةِ والباطنة؛ فالعبادةُ هي غايةُ وجودك وسرُّ خلقك؛ فمن عبد الله وحقّق الغايةَ من خلقه سعد، ومن أعرض عن العبادةِ ضلّ وشقي؛ فاجعل تحقيقَ الغايةِ من خلقك بعبادةِ الله وحده دأبك؛ فبالعبادةِ تحقّق سرَّ وجودك."}},{"n":57,"reflection":{"text":"«ما أريد منهم من رزق وما أريد أن يطعمون»: ما أريد منهم رزقًا ولا أريد أن يطعموني؛ ففي هذا بيانُ غنى الله عن خلقه؛ فاعلم أنّ الله غنيٌّ عنك، وأنّ عبادتك لنفعك لا لنفعه، فاعبده لأنه يستحقّ العبادة، لا لحاجةٍ منه إليك، فالله الغنيُّ وأنت الفقير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ غنى الله عن خلقه، وأنّ العبادةَ لنفعِ العبد."},"action":{"text":"تأمّل غنى الله عن خلقه: ما أريد من الجنِّ والإنسِ من رزقٍ يرزقونني، ولا أريد أن يطعموني؛ فأنا الغنيُّ عنهم وعن عبادتهم، لا حاجةَ لي إليهم؛ وإنما أمرتهم بالعبادةِ لنفعهم هم «ما أريد منهم من رزق وما أريد أن يطعمون»؛ ففي هذا بيانُ غنى الله التامِّ عن خلقه، وأنه لا يريد منهم رزقًا ولا طعامًا؛ فعبادتهم لا تنفعه، وتركها لا يضرّه؛ فاعلم أنت أنّ الله غنيٌّ عنك وعن عبادتك؛ فعبادتك لنفعك أنت لا لنفعه سبحانه؛ يا أيها الناس أنتم الفقراء إلى الله والله هو الغنيُّ الحميد؛ من عمل صالحًا فلنفسه؛ إن أحسنتم أحسنتم لأنفسكم؛ يا عبادي لو أنّ أوّلكم وآخركم... كانوا على أتقى قلبِ رجلٍ واحدٍ ما زاد ذلك في ملكي شيئًا؛ فاعبد الله لأنه يستحقّ العبادةَ لذاته، لا لحاجةٍ منه إليك؛ فالله الغنيُّ وأنت الفقيرُ المحتاجُ إليه؛ فمن عبد الله مدركًا غناه عنه أخلص، ومن ظنّ أنه ينفع الله بعبادته جهل؛ فاجعل إدراكَ غنى الله عنك وأنّ عبادتك لنفعك دأبك."}},{"n":58,"reflection":{"text":"«إن الله هو الرزاق ذو القوة المتين»: إنّ الله هو الرزّاقُ لجميعِ خلقه، ذو القوّةِ الشديدةِ المتينِ الذي لا يضعف؛ ففي هذا بيانُ أنّ الله وحده الرزّاق؛ فاطلب رزقك من الله الرزّاقِ القويّ، وتوكّل عليه، فالرزقُ بيده وحده، فلا تعتمد في رزقك على غيره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الرزقِ من الله الرزّاقِ القويّ، والتوكّلُ عليه وحده."},"action":{"text":"تأمّل أنّ الله هو الرزّاق: إنّ الله وحده هو الرزّاقُ الذي يرزق جميعَ خلقه، كثيرُ الرزقِ واسعه؛ ذو القوّةِ الشديدةِ العظيمة؛ المتينُ الشديدُ القوّةِ الذي لا يضعف ولا يعجز؛ فرزقه بقوّته لا ينقطع «إن الله هو الرزاق ذو القوة المتين»؛ ففي هذا بيانُ أنّ الله وحده هو الرزّاقُ لجميعِ الخلق، وأنه القويُّ المتينُ الذي لا يعجزه شيء؛ فالرزقُ بيده وحده يعطيه بقوّته؛ فاطلب أنت رزقك من الله الرزّاقِ القويِّ المتين؛ وما من دابّةٍ في الأرضِ إلا على الله رزقها؛ وكأيّن من دابّةٍ لا تحمل رزقها الله يرزقها وإياكم؛ وتوكّل على الله في رزقك؛ ومن يتوكّل على الله فهو حسبه؛ ولو أنّ أهلَ القرى آمنوا واتّقوا لفتحنا عليهم بركاتٍ من السماءِ والأرض؛ فالرزقُ بيدِ الله وحده، فلا تعتمد فيه على غيره؛ فمن طلب الرزقَ من الله وتوكّل عليه كُفِي، ومن اعتمد على غيره خُذِل؛ فاجعل طلبَ الرزقِ من الله والتوكّلَ عليه دأبك."}},{"n":59,"reflection":{"text":"«فإن للذين ظلموا ذنوبا مثل ذنوب أصحابهم فلا يستعجلون»: فإنّ للذين ظلموا (كفروا) نصيبًا من العذابِ مثلَ نصيبِ أشباههم من الأممِ السابقة، فلا يستعجلوني بالعذاب؛ ففي هذا وعيدُ الظالمين بمثلِ عذابِ من قبلهم؛ فاحذر الظلمَ والكفرَ فإنّ لك نصيبًا من العذابِ كمن قبلك، فلا تأمن العذابَ، فبادر بالتوبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ والكفر، والمبادرةُ بالتوبةِ قبل العذاب."},"action":{"text":"تأمّل وعيدَ الظالمين: فإنّ للذين ظلموا أنفسهم بالكفرِ والتكذيبِ من قومك نصيبًا وحظًّا من العذابِ مثلَ نصيبِ أصحابهم وأشباههم من الأممِ المكذّبةِ السابقةِ التي أُهلِكت؛ فلا يستعجلوني بالعذاب، فإنه آتيهم في وقته المقدّر «فإن للذين ظلموا ذنوبا مثل ذنوب أصحابهم فلا يستعجلون»؛ ففي هذا وعيدُ الظالمين المكذّبين بأنّ لهم نصيبًا من العذابِ مثلَ من قبلهم، وأنه لا ينبغي استعجاله؛ فمصيرهم كمصيرِ من قبلهم إن استمرّوا؛ فاحذر أنت الظلمَ والكفرَ والتكذيب؛ فإنّ لك نصيبًا من العذابِ كمن قبلك إن سلكت سبيلهم؛ فلا تأمن العذابَ ولا تستعجله؛ ولا تحسبنّ الله غافلًا عمّا يعمل الظالمون؛ فبادر بالتوبةِ والإيمانِ والعملِ الصالحِ قبل نزولِ العذاب؛ فمن تاب وآمن نجا، ومن ظلم وكذّب ناله نصيبه من العذاب؛ فاجعل الحذرَ من الظلمِ والمبادرةَ بالتوبةِ دأبك."}},{"n":60,"reflection":{"text":"«فويل للذين كفروا من يومهم الذي يوعدون»: فويلٌ وهلاكٌ للذين كفروا من يومهم الذي يُوعَدون به (يومِ القيامةِ أو بدر)؛ ففي هذا ختامُ السورةِ بوعيدِ الكافرين؛ فاحذر أن تكون من الكافرين الذين لهم الويلُ يومَ الوعيد، فآمن واعمل لتنجو، فالكفرُ يورث الويلَ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والعملُ للنجاة، والحذرُ من الويلِ يومَ الوعيد."},"action":{"text":"تأمّل ختامَ السورةِ بالوعيد: فويلٌ، أي هلاكٌ وعذابٌ شديد، أو وادٍ في جهنّم، للذين كفروا بالله ورسوله واليومِ الآخر؛ من يومهم الذي يُوعَدون به، وهو يومُ القيامةِ الذي فيه حسابهم وعذابهم، أو يومُ بدرٍ الذي هُزِموا فيه «فويل للذين كفروا من يومهم الذي يوعدون»؛ ففي هذا ختامُ السورةِ بوعيدِ الكافرين بالويلِ والهلاكِ يومَ القيامة؛ فلهم الويلُ والعذابُ من ذلك اليوم؛ فاحذر أنت أن تكون من الكافرين الذين لهم الويلُ يومَ الوعيد؛ فآمن بالله ورسوله واليومِ الآخر، واعمل صالحًا لتنجو من الويلِ والعذاب؛ فويلٌ للكافرين من عذابٍ شديد؛ فالكفرُ يورث الويلَ والهلاكَ يومَ القيامة؛ فمن آمن وعمل صالحًا نجا، ومن كفر فله الويلُ يومَ الوعيد؛ فاجعل الإيمانَ والعملَ الصالحَ سبيلَ نجاتك من الويل."}}]}],"coverage":{"covered":60,"total":60}};
